func exportCmd() *cobra.Command {
	var output string
	var full bool
	var toRepo bool

	cmd := &cobra.Command{
		Use:   "export <feature>",
		Short: "Export workspace metadata for portability",
		Long: `Export a feature's workspace metadata (stack, decisions) to YAML or tarball.

  tws export auth                          # YAML to stdout
  tws export auth -o auth.yaml             # YAML to file
  tws export auth --full -o auth.tar.gz    # tarball with inject files
  tws export auth --to-repo                # save to .tws/workspaces/ (committed)`,
		Args: cobra.ExactArgs(1),
		ValidArgsFunction: func(cmd *cobra.Command, args []string, toComplete string) ([]string, cobra.ShellCompDirective) {
			if len(args) == 0 {
				ws, err := internal.RequireWorkspace()
				if err != nil {
					return nil, cobra.ShellCompDirectiveNoFileComp
				}
				ws, err = managedTemplateExecutionWorkspace(ws)
				if err != nil {
					return nil, cobra.ShellCompDirectiveNoFileComp
				}
				features, err := ws.ListFeaturesResolved()
				if err != nil {
					return nil, cobra.ShellCompDirectiveNoFileComp
				}
				return features, cobra.ShellCompDirectiveNoFileComp
			}
			return nil, cobra.ShellCompDirectiveNoFileComp
		},
		RunE: func(cmd *cobra.Command, args []string) error {
			feature := args[0]

			ws, err := internal.RequireWorkspace()
			if err != nil {
				return err
			}

			context, err := resolveFeatureContext(ws, feature)
			if err != nil {
				return err
			}
			ws = context.Workspace
			featurePath := context.FeaturePath

			if _, err := os.Stat(featurePath); os.IsNotExist(err) {
				return fmt.Errorf("feature not found: %s", feature)
			}
			managed, err := internal.ManagedTemplateStatePresent(featurePath)
			if err != nil {
				return err
			}
			if managed {
				if _, err := fmt.Fprintln(cmd.ErrOrStderr(), "Warning: export omits managed template selections, ownership metadata, external-link ownership, and orchestrator assets; imported inject files remain unmanaged."); err != nil {
					return err
				}
			}

			stack, _ := internal.LoadStack(featurePath)
			decisions, _ := internal.LoadDecisions(featurePath)
			export := internal.NewWorkspaceExport(feature, stack, decisions)

			if toRepo {
				if ws.Mode == internal.ModeCheckout {
					return fmt.Errorf("--to-repo is not supported in checkout mode; use '-o <tracked-path>' to write to a tracked file instead")
				}
				return exportToRepo(ws.RepoRoot, feature, export)
			}

			if full {
				return exportTarball(feature, featurePath, export, output)
			}

			return exportYAML(export, output)
		},
	}

	cmd.Flags().StringVarP(&output, "output", "o", "", "Output file (default: stdout)")
	cmd.Flags().BoolVar(&full, "full", false, "Include inject files in a tarball")
	cmd.Flags().BoolVar(&toRepo, "to-repo", false, "Save to .tws/workspaces/ in the repo")

	return cmd
}

func exportYAML(export internal.WorkspaceExport, output string) error {
	data, err := internal.MarshalExport(export)
	if err != nil {
		return fmt.Errorf("marshaling export: %w", err)
	}

	if output == "" {
		fmt.Print(string(data))
	} else {
		if err := os.WriteFile(output, data, 0644); err != nil {
			return fmt.Errorf("writing %s: %w", output, err)
		}
		fmt.Printf("Exported to: %s\n", output)
	}
	return nil
}

func exportToRepo(repoRoot, feature string, export internal.WorkspaceExport) error {
	dir := filepath.Join(repoRoot, ".tws", "workspaces")
	if err := os.MkdirAll(dir, 0755); err != nil {
		return err
	}

	path := filepath.Join(dir, feature+".yaml")
	data, err := internal.MarshalExport(export)
	if err != nil {
		return err
	}

	if err := os.WriteFile(path, data, 0644); err != nil {
		return err
	}

	fmt.Printf("Exported to: %s\n", path)
	fmt.Println("Commit and push to share with team members.")
	return nil
}

// exportTarball creates a tarball with durable metadata and inject files.
// Runtime state (.tws/state) is structurally excluded.
func exportTarball(feature, featurePath string, export internal.WorkspaceExport, output string) error {
	if output == "" {
		output = feature + "-workspace.tar.gz"
	}

	f, err := os.Create(output)
	if err != nil {
		return fmt.Errorf("creating %s: %w", output, err)
	}
	defer f.Close() //nolint:errcheck

	gw := gzip.NewWriter(f)
	defer gw.Close() //nolint:errcheck

	tw := tar.NewWriter(gw)
	defer tw.Close() //nolint:errcheck

	// Write workspace.yaml
	yamlData, _ := internal.MarshalExport(export)
	addToTar(tw, "workspace.yaml", yamlData)

	// Write inject files only (exclude runtime state structurally)
	injectDir := internal.InjectPath(featurePath)
	if _, err := os.Stat(injectDir); err == nil {
		_ = filepath.Walk(injectDir, func(path string, info os.FileInfo, err error) error {
			if err != nil || info.IsDir() {
				if err == nil && info != nil && info.IsDir() &&
					filepath.Base(path) == ".tws-template-recovery" {
					return filepath.SkipDir
				}
				return nil
			}
			relPath, _ := filepath.Rel(featurePath, path)
			// Structurally exclude runtime state: only include inject/ prefix
			if !strings.HasPrefix(relPath, "inject/") && !strings.HasPrefix(relPath, "inject\\") {
				return nil
			}
			data, err := os.ReadFile(path)
			if err != nil {
				return nil
			}
			addToTar(tw, relPath, data)
			return nil
		})
	}

	fmt.Printf("Exported to: %s\n", output)
	return nil
}

func addToTar(tw *tar.Writer, name string, data []byte) {
	header := &tar.Header{
		Name: name,
		Mode: 0644,
		Size: int64(len(data)),
	}
	_ = tw.WriteHeader(header)
	_, _ = tw.Write(data)
}

package cli

import (
	"errors"
	"fmt"
	"os"

	"github.com/jdbencardinop/tesseraworkspaces/internal"
	"github.com/spf13/cobra"
)

func injectCmd() *cobra.Command {
	var into string

	cmd := &cobra.Command{
		Use:   "inject <feature> [branch]",
		Short: "Sync inject/ files into worktrees",
		Long: `Re-sync shared files from inject/ into external linked worktrees.
With no branch, syncs every materialized worktree discovered for the feature,
including logical names that contain slashes. Checkout mode is unsupported
because it has one physical checkout and no linked worktrees.

Injected files are symlinked into the worktree. By default they go to
the worktree root. Use --into to target a subdirectory (e.g., --into .context).
For managed worktree guidance, root injection is required: an explicit
--into . overrides a configured non-root inject_into for this invocation,
while an explicit non-root --into is refused.

Set inject_into in config to change the default:
  tws config set inject_into .context
  tws config set inject_into .context --repo

Tip: To keep git status clean, either:
  - Add injected filenames to .gitignore (e.g., CLAUDE.local.md)
  - Use --into to target a gitignored subfolder (e.g., --into .context)
  - Or nest inside an already-ignored dir like inject/.claude/`,
		Args: cobra.RangeArgs(1, 2),
		ValidArgsFunction: func(cmd *cobra.Command, args []string, toComplete string) ([]string, cobra.ShellCompDirective) {
			switch len(args) {
			case 0:
				return managedCompletionFeatures(), cobra.ShellCompDirectiveNoFileComp
			case 1:
				return managedCompletionBranches(args[0]), cobra.ShellCompDirectiveNoFileComp
			default:
				return nil, cobra.ShellCompDirectiveNoFileComp
			}
		},
		RunE: func(cmd *cobra.Command, args []string) error {
			feature := args[0]
			ws, err := internal.RequireWorkspace()
			if err != nil {
				return err
			}
			ws, err = managedTemplateWorkspaceForFeature(ws, feature)
			if err != nil {
				return err
			}
			featurePath, err := internal.ResolveFeaturePathFor(ws, feature)
			if err != nil {
				return err
			}
			if ws.Mode == internal.ModeCheckout {
				return internal.ErrWorktreeUnsupported
			}

			injectDir := internal.InjectPath(featurePath)
			if _, err := os.Stat(injectDir); os.IsNotExist(err) {
				return fmt.Errorf("no inject/ directory found for feature: %s\nCreate it at: %s", feature, injectDir)
			}

			managed, err := internal.ManagedTemplateStatePresent(featurePath)
			if err != nil {
				return err
			}
			target := internal.ResolveInjectInto(into)
			managedTarget := managedInjectTarget{Value: target}
			if managed {
				cfg, err := resolveManagedConfig(ws)
				if err != nil {
					return err
				}
				managedTarget.Value = cfg.Config.InjectInto
				managedTarget.Explicit = cmd.Flags().Changed("into")
				if managedTarget.Explicit {
					managedTarget.Value = into
				}
				target = managedTarget.Value
			}

			if len(args) == 2 {
				branch := args[1]
				path, err := internal.ResolveInjectWorktree(featurePath, branch)
				if errors.Is(err, internal.ErrInjectWorktreeNotFound) {
					return fmt.Errorf("worktree not found: %s/%s", feature, branch)
				}
				if err != nil {
					return err
				}
				if managed {
					if err := syncManagedAndLegacyInject(
						cmd, ws, feature, featurePath, branch, path, managedTarget,
					); err != nil {
						return err
					}
				} else if err := internal.InjectFiles(featurePath, path, target); err != nil {
					return err
				}
				if target != "" && target != "." {
					fmt.Printf("Injected files into: %s/%s/%s\n", feature, branch, target)
				} else {
					fmt.Printf("Injected files into: %s/%s\n", feature, branch)
				}
			} else {
				var count int
				if managed {
					count, err = syncManagedAndLegacyInjectAll(
						cmd, ws, feature, featurePath, managedTarget,
					)
				} else {
					count, err = internal.InjectFilesForFeature(featurePath, target)
				}
				if err != nil {
					return err
				}
				fmt.Printf("Injected files into %d worktree(s)\n", count)
			}
			return nil
		},
	}

	cmd.Flags().StringVar(&into, "into", "", "Target subdirectory; managed guidance accepts only root, and --into . overrides configured inject_into")

	return cmd
}

