		if _, err := os.Lstat(path); !errors.Is(err, os.ErrNotExist) {
			t.Fatalf("consented retirement left %s: %v", path, err)
		}
	}
}

package cli

import (
	"fmt"
	"os"
	"os/exec"
	"path/filepath"
	"strings"

	"github.com/jdbencardinop/tesseraworkspaces/internal"
	"github.com/spf13/cobra"
)

var creationResolvedHook func(repoRoot, baseRef, resolvedSHA string) error

func newCmd() *cobra.Command {
	var base string
	var force bool
	var repo string

	cmd := &cobra.Command{
		Use:   "new <feature> <branch>",
		Short: "Create a worktree branch",
		Args:  cobra.ExactArgs(2),
		ValidArgsFunction: func(cmd *cobra.Command, args []string, toComplete string) ([]string, cobra.ShellCompDirective) {
			switch len(args) {
			case 0:
				return managedCompletionFeatures(), cobra.ShellCompDirectiveNoFileComp
			case 1:
				return managedCompletionBranches(args[0]), cobra.ShellCompDirectiveNoFileComp
			default:
				return nil, cobra.ShellCompDirectiveNoFileComp
			}
		},
		RunE: func(cmd *cobra.Command, args []string) error {
			ws, err := internal.RequireWorkspace()
			if err != nil {
				return err
			}
			if ws.Mode == internal.ModeCheckout {
				if repo != "" {
					return fmt.Errorf("--repo is not supported in checkout mode; checkout workspaces use exactly one repository")
				}
				return createCheckoutBranch(ws, args[0], args[1], base, force)
			}
			ws, err = managedTemplateWorkspaceForFeature(ws, args[0])
			if err != nil {
				return err
			}
			featurePath, err := ws.ResolveFeaturePath(args[0])
			if err != nil {
				return err
			}
			managed, err := internal.ManagedTemplateStatePresent(featurePath)
			if err != nil {
				return err
			}
			if managed {
				return createWorktreeResolved(ws, args[0], args[1], base, repo, force)
			}
			return createWorktree(args[0], args[1], base, repo, force)
		},
	}

	cmd.Flags().StringVar(&base, "base", "", "Parent branch, tag, or commit (default: selected repo's origin/HEAD)")
	cmd.Flags().BoolVarP(&force, "force", "f", false, "Force checkout of already checked-out branch")
	cmd.Flags().StringVar(&repo, "repo", "", "Source repository path (for cross-repo worktrees)")

	return cmd
}

// createCheckoutBranch creates a git branch for checkout mode (no worktree).
// Atomic: if metadata persistence fails after branch creation, the branch is
// rolled back (only if this operation created it). Archived entries are
// reactivated. Mismatched existing entries are rejected.
func createCheckoutBranch(ws internal.Workspace, feature, name, requestedBase string, force bool) error {
	if err := internal.GuardFeatureName(ws.MetadataRoot, feature); err != nil {
		return err
	}

	featurePath, err := ws.ResolveFeaturePath(feature)
	if err != nil {
		return err
	}

	// Pre-validate feature directory exists.
	if _, err := os.Stat(featurePath); os.IsNotExist(err) {
		return fmt.Errorf("feature %q not found; run 'tws add %s' first", feature, feature)
	}

	stack, _ := internal.LoadStack(featurePath)

	repoRoot := ws.RepoRoot

	baseName, baseRef, err := resolveCreationBase(repoRoot, "", stack, requestedBase)
	if err != nil {
		return err
	}

	cfg := internal.LoadConfig()
	gitBranch := name
	if cfg.BranchPrefix != "" {
		gitBranch = cfg.BranchPrefix + name
	}

	branchExisted := internal.VerifyGitRef(repoRoot, gitBranch) == nil
	if !branchExisted && gitBranch != name && internal.VerifyGitRef(repoRoot, name) == nil {
		gitBranch = name
		branchExisted = true
	}

	// Check for existing stack entry.
	existing := internal.GetBranch(stack, name)
	if existing.Name != "" {
		// If archived, reactivate.
		if existing.Archived {
			for i := range stack.Branches {
				if stack.Branches[i].Name == name {
					stack.Branches[i].Archived = false
					break
				}
			}
			if err := internal.SaveStack(featurePath, stack); err != nil {
				return fmt.Errorf("failed to unarchive branch: %w", err)
			}
			fmt.Printf("Reactivated archived branch: %s (git: %s)\n", name, existing.GitBranch())
			return nil
		}
		// Existing non-archived entry: validate consistency.
		expectedBranch := gitBranch
		if existing.Branch != "" {
			expectedBranch = existing.Branch
		}
		if existing.GitBranch() != expectedBranch && existing.GitBranch() != gitBranch {
			return fmt.Errorf("branch %q already registered with git branch %q (expected %q); use rename or delete first",
				name, existing.GitBranch(), gitBranch)
		}
		fmt.Printf("Branch %s already registered (git: %s)\n", name, existing.GitBranch())
		return nil
	}

	// Create git branch if it does not exist.
	var creationSHA string
	if !branchExisted {
		creationSHA, err = resolveCreationCommit(repoRoot, baseRef)
		if err != nil {
			return err
		}
		if creationResolvedHook != nil {
			if err := creationResolvedHook(repoRoot, baseRef, creationSHA); err != nil {
				return err
			}
		}
		if err := internal.RunDir(repoRoot, "git", "branch", gitBranch, creationSHA); err != nil {
			return fmt.Errorf("creating git branch %s: %w", gitBranch, err)
		}
	}

	// Register in stack.
	entry := internal.StackEntry{
		Name:        name,
		Base:        baseName,
		LastBaseSHA: creationSHA,
	}
	if gitBranch != name {
		entry.Branch = gitBranch
	}
	stack.Branches = append(stack.Branches, entry)

	if err := internal.SaveStack(featurePath, stack); err != nil {
		// Rollback: only delete branch if we created it.
		if !branchExisted {
			_ = internal.RunSilentDir(repoRoot, "git", "branch", "-d", gitBranch)
		}
		return fmt.Errorf("failed to persist stack (branch rolled back): %w", err)
	}

	fmt.Printf("Branch created: %s (git: %s, base: %s)\n", name, gitBranch, baseName)
	return nil
}

// openCheckoutTmux opens a tmux session for a checkout-mode branch.
func openCheckoutTmux(ws internal.Workspace, feature, branch string) {
	session := sanitizeSessionName(feature + "/" + branch)
	fmt.Printf("Checkout branch: use 'git checkout %s' then 'tmux new-session -s %s'\n", branch, session)
}

// createWorktree is the shared logic for creating a worktree branch (external mode).
// Used by both tws new and tws add -n. Explicit base refs are literal;
// an omitted base resolves from the selected repository's origin/HEAD.
func createWorktree(feature, name, requestedBase, repoPath string, force bool) error {
	wsRoot := internal.TwsRoot()
	return createWorktreeAt(
		internal.Workspace{Mode: internal.ModeExternal, MetadataRoot: wsRoot},
		feature, internal.FeaturePath(feature), internal.WorktreePath(feature, name),
		name, requestedBase, repoPath, force,
	)
}

func createWorktreeResolved(ws internal.Workspace, feature, name, requestedBase, repoPath string, force bool) error {
	featurePath, err := ws.ResolveFeaturePath(feature)
	if err != nil {
		return err
	}
	cfg, err := internal.LoadConfigForRepoE(ws.RepoRoot)
	if err != nil {
		return err
	}
	if err := internal.ValidateManagedCheckoutContextResolved(
		ws, feature, featurePath, cfg.GetAgentCommand(), cfg.InjectInto, false,
	); err != nil {
		return err
	}
	repoRoot := ws.RepoRoot
	storedRepo := ""
	if repoPath != "" {
		repoRoot, storedRepo, err = resolveSourceRepo(featurePath, internal.Stack{}, repoPath)
		if err != nil {
			return err
		}
	}
	return createWorktreeAt(
		ws, feature, featurePath, filepath.Join(featurePath, "worktrees", filepath.FromSlash(name)),
		name, requestedBase, repoPath, force,
		&worktreeCreationSelection{
			repoRoot: repoRoot, storedRepo: storedRepo, cfg: cfg,
			inject: managedInjectTarget{Value: cfg.InjectInto},
		},
	)
}

type worktreeCreationSelection struct {
	repoRoot   string
	storedRepo string
	cfg        internal.Config
	inject     managedInjectTarget
}

func createWorktreeAt(
	ws internal.Workspace,
	feature, featurePath, path, name, requestedBase, repoPath string,
	force bool,
	selections ...*worktreeCreationSelection,
) error {
	wsRoot := ws.MetadataRoot
	if err := internal.GuardFeatureName(wsRoot, feature); err != nil {
		return err
	}

	if err := internal.EnsureExternalWorkspaceMarker(wsRoot); err != nil {
		return err
	}
	if err := os.MkdirAll(featurePath, 0755); err != nil {
		return err
	}

	stack, _ := internal.LoadStack(featurePath)
	existingEntry := internal.GetBranch(stack, name)
	reactivating := existingEntry.Name != "" && existingEntry.Archived
	var repoRoot, storedRepo string
	var err error
	cfg := internal.LoadConfig()
	injectTarget := managedInjectTarget{Value: internal.ResolveInjectInto("")}
	if len(selections) > 0 && selections[0] != nil {
		repoRoot = selections[0].repoRoot
		storedRepo = selections[0].storedRepo
		cfg = selections[0].cfg
		injectTarget = selections[0].inject
	} else {
		repoRoot, storedRepo, err = resolveSourceRepo(featurePath, stack, repoPath)
		if err != nil {
			return err
		}
	}
	if reactivating {
		storedRepo = existingEntry.Repo
		repoRoot = ws.RepoRoot
		if storedRepo != "" {
			repoRoot, err = internal.MainRepoRootIn(storedRepo)
			if err != nil {
				return fmt.Errorf("resolving stored repository for archived entry %q: %w", name, err)
			}
		}
		if repoPath != "" {
			requestedRoot, _, resolveErr := resolveSourceRepo(featurePath, internal.Stack{}, repoPath)
			if resolveErr != nil {
				return resolveErr
			}
			if !sameResolvedRepoRoot(repoRoot, requestedRoot) {
				return fmt.Errorf("archived entry %q belongs to a different repository (%s)", name, repoRoot)
			}
		}
	}

	baseName := existingEntry.Base
	baseRef := ""
	if !reactivating {
		baseName, baseRef, err = resolveCreationBase(repoRoot, storedRepo, stack, requestedBase)
		if err != nil {
			return err
		}
	}

	gitBranch := existingEntry.GitBranch()
	if !reactivating {
		gitBranch = name
	}
	if !reactivating && cfg.BranchPrefix != "" {
		gitBranch = cfg.BranchPrefix + name
	}

	branchExists := internal.VerifyGitRef(repoRoot, gitBranch) == nil
	if reactivating && !branchExists {
		return fmt.Errorf("archived entry %q references missing git branch %q in %s", name, gitBranch, repoRoot)
	}
	if !branchExists && gitBranch != name && internal.VerifyGitRef(repoRoot, name) == nil {
		gitBranch = name
		branchExists = true
	}

	var creationSHA string
	if branchExists {
		if isCheckedOutIn(repoRoot, gitBranch) && !force {
			return fmt.Errorf("branch %q is already checked out in another worktree; use --force to check it out anyway", gitBranch)
		}

		gitArgs := []string{"worktree", "add"}
		if force {
			gitArgs = append(gitArgs, "--force")
		}
		gitArgs = append(gitArgs, path, gitBranch)
		if err := internal.RunDir(repoRoot, "git", gitArgs...); err != nil {
			return err
		}
	} else {
		creationSHA, err = resolveCreationCommit(repoRoot, baseRef)
		if err != nil {
			return err
		}
		if creationResolvedHook != nil {
			if err := creationResolvedHook(repoRoot, baseRef, creationSHA); err != nil {
				return err
			}
		}
		if err := internal.RunDir(repoRoot, "git", "worktree", "add", path, "-b", gitBranch, creationSHA); err != nil {
			return err
		}
	}

	if !internal.HasBranch(stack, name) {
		entry := internal.StackEntry{
			Name:        name,
			Base:        baseName,
			Repo:        storedRepo,
			LastBaseSHA: creationSHA,
		}
		if gitBranch != name {
			entry.Branch = gitBranch
		}
		stack.Branches = append(stack.Branches, entry)
		if err := internal.SaveStack(featurePath, stack); err != nil {
			return err
		}
	} else {
		for i := range stack.Branches {
			if stack.Branches[i].Name == name && stack.Branches[i].Archived {
				stack.Branches[i].Archived = false
				if err := internal.SaveStack(featurePath, stack); err != nil {
					return fmt.Errorf("failed to reactivate archived worktree metadata: %w", err)
				}
				break
			}
		}
	}

	managed, managedErr := internal.ManagedTemplateStatePresent(featurePath)
	if managedErr != nil {
		return managedErr
	}
	if managed {
		resolvedWS := ws
		if resolvedWS.RepoRoot == "" {
			var err error
			resolvedWS, err = internal.RequireWorkspace()
			if err != nil {
				return err
			}
		}
		if err := syncManagedAndLegacyInject(
			nil, resolvedWS, feature, featurePath, name, path,
			injectTarget,
		); err != nil {
			return fmt.Errorf("managed inject failed after worktree creation: %w", err)
		}
	} else if err := internal.InjectFiles(featurePath, path, injectTarget.Value); err != nil {
		fmt.Printf("Warning: inject failed: %v\n", err)
	}

	if cfg.AutoHooks != nil && *cfg.AutoHooks {
		if err := installHooksForWorktree(path, feature); err != nil {
			fmt.Printf("Warning: auto-hooks install failed: %v\n", err)
		}
	}

	if storedRepo != "" {
		fmt.Printf("Worktree created: %s (base: %s, repo: %s)\n", path, baseName, storedRepo)
	} else {
		fmt.Printf("Worktree created: %s (base: %s)\n", path, baseName)
	}
	return nil
}

func resolveSourceRepo(featurePath string, stack internal.Stack, requestedRepo string) (string, string, error) {
	if requestedRepo != "" {
		absRepo, err := internal.AbsPath(requestedRepo)
		if err != nil {
			return "", "", fmt.Errorf("invalid repo path %s: %w", requestedRepo, err)
		}
		repoRoot, err := internal.GitRepoRootIn(absRepo)
		if err != nil {
			return "", "", fmt.Errorf("%s is not a Git repository", requestedRepo)
		}
		return repoRoot, repoRoot, nil
	}

	if repoRoot, err := internal.MainRepoRoot(); err == nil {
		return repoRoot, "", nil
	}

	type candidate struct {
		root       string
		storedRepo string
	}
	candidates := make(map[string]candidate)
	for _, entry := range stack.Branches {
		if entry.Repo != "" {
			root, err := internal.GitRepoRootIn(entry.Repo)
			if err == nil {
				candidates[root] = candidate{root: root, storedRepo: root}
			}
			continue
		}

		worktreePath := filepath.Join(featurePath, "worktrees", entry.Name)
		if _, err := os.Stat(worktreePath); err != nil {
			continue
		}
		root, err := internal.MainRepoRootIn(worktreePath)
		if err == nil {
			candidates[root] = candidate{root: root}
		}
	}

	if len(candidates) == 1 {
		for _, c := range candidates {
			return c.root, c.storedRepo, nil
		}
	}
	if len(candidates) > 1 {
		return "", "", fmt.Errorf("feature uses multiple repositories; specify --repo")
	}
	return "", "", fmt.Errorf("could not infer source repository; run from a Git repo or specify --repo")
}

func resolveCreationBase(repoRoot, storedRepo string, stack internal.Stack, requestedBase string) (string, string, error) {
	if requestedBase == "" {
		baseName, err := internal.DefaultBranchIn(repoRoot)
		if err != nil {
			return "", "", err
		}
		remoteRef := "origin/" + baseName
		if internal.VerifyGitRef(repoRoot, remoteRef) == nil {
			return baseName, remoteRef, nil
		}
		if internal.VerifyGitRef(repoRoot, baseName) == nil {
			return baseName, baseName, nil
		}
		return "", "", fmt.Errorf("default branch %q does not exist in %s", baseName, repoRoot)
	}

	baseRef := requestedBase
	if parent := internal.GetBranch(stack, requestedBase); parent.Name != "" {
		if !sameStackRepo(parent.Repo, storedRepo) {
			return "", "", fmt.Errorf("base %q belongs to a different repository", requestedBase)
		}
		baseRef = parent.GitBranch()
	}
	if err := internal.VerifyGitRef(repoRoot, baseRef); err != nil {
		return "", "", fmt.Errorf("base ref %q does not exist in %s", requestedBase, repoRoot)
	}
	return requestedBase, baseRef, nil
}

func resolveCreationCommit(repoRoot, baseRef string) (string, error) {
	cmd := exec.Command("git", "-C", repoRoot, "rev-parse", "--verify", "--quiet", "--end-of-options", baseRef+"^{commit}")
	out, err := cmd.CombinedOutput()
	if err != nil {
		return "", fmt.Errorf("resolve creation base %q in %s: %s", baseRef, repoRoot, strings.TrimSpace(string(out)))
	}
	sha := strings.ToLower(strings.TrimSpace(string(out)))
	if len(sha) != 40 && len(sha) != 64 {
		return "", fmt.Errorf("resolve creation base %q in %s: Git returned invalid object id %q", baseRef, repoRoot, sha)
	}
	for _, r := range sha {
		if (r < '0' || r > '9') && (r < 'a' || r > 'f') {
			return "", fmt.Errorf("resolve creation base %q in %s: Git returned invalid object id %q", baseRef, repoRoot, sha)
		}
	}
	return sha, nil
}

func sameStackRepo(a, b string) bool {
	return internal.SameStackRepo(a, b)
}

func isCheckedOutIn(repoRoot, branch string) bool {
	out, err := exec.Command("git", "-C", repoRoot, "worktree", "list", "--porcelain").Output()
	if err != nil {
		return false
	}
	for line := range strings.SplitSeq(string(out), "\n") {
		if strings.TrimSpace(line) == "branch refs/heads/"+branch {
			return true
		}
	}
	return false
}

package cli

import (
	"errors"
	"fmt"
	"os"
	"os/exec"
	"path/filepath"
	"strings"

	"github.com/jdbencardinop/tesseraworkspaces/internal"
	"github.com/spf13/cobra"
)

func openCmd() *cobra.Command {
	var useTmux bool
	var noTmux bool
	var noAgent bool
	var featureDir bool
	var all bool

	cmd := &cobra.Command{
		Use:   "open [feature] [branch]",
		Short: "Open worktree and run agent",
		Long: `Open a worktree and run the configured agent. With no args, shows an interactive picker.

Use --feature-dir to open the feature directory itself (orchestrator mode).
Use --all to create a tmux session with windows for every worktree in the feature.`,
		Args: cobra.RangeArgs(0, 2),
		ValidArgsFunction: func(cmd *cobra.Command, args []string, toComplete string) ([]string, cobra.ShellCompDirective) {
			switch len(args) {
			case 0:
				ws, err := internal.RequireWorkspace()
				if err != nil {
					return nil, cobra.ShellCompDirectiveNoFileComp
				}
				ws, err = managedTemplateExecutionWorkspace(ws)
				if err != nil {
					return nil, cobra.ShellCompDirectiveNoFileComp
				}
				features, err := ws.ListFeaturesResolved()
				if err != nil {
					return nil, cobra.ShellCompDirectiveNoFileComp
				}
				return features, cobra.ShellCompDirectiveNoFileComp
			case 1:
				ws, err := internal.RequireWorkspace()
				if err != nil {
					return nil, cobra.ShellCompDirectiveNoFileComp
				}
				context, err := resolveFeatureContext(ws, args[0])
				if err != nil {
					return nil, cobra.ShellCompDirectiveNoFileComp
				}
				return internal.ListBranchesAt(context.FeaturePath), cobra.ShellCompDirectiveNoFileComp
			default:
				return nil, cobra.ShellCompDirectiveNoFileComp
			}
		},
		RunE: func(cmd *cobra.Command, args []string) error {
			ws, err := internal.RequireWorkspace()
			if err != nil {
				return err
			}
			// Checkout mode: delegate to checkout session flow
			if ws.Mode == internal.ModeCheckout {
				if all {
					return fmt.Errorf("--all not supported in checkout mode")
				}

				// --feature-dir handled before branch resolution
				if featureDir {
					if len(args) < 1 {
						return fmt.Errorf("usage: tws open <feature> --feature-dir")
					}
					feature := args[0]
					if gerr := internal.GuardFeatureName(ws.MetadataRoot, feature); gerr != nil {
						return gerr
					}
					fp, ferr := ws.ResolveFeaturePath(feature)
					if ferr != nil {
						return ferr
					}
					managed, ferr := internal.ManagedTemplateStatePresent(fp)
					if ferr != nil {
						return ferr
					}
					var managedCfg resolvedManagedConfig
					if managed {
						managedCfg, ferr = resolveManagedConfig(ws)
						if ferr != nil {
							return ferr
						}
						if ferr := internal.ValidateManagedOrchestratorContext(
							ws, feature, fp, managedCfg.AgentCommand,
						); ferr != nil {
							return ferr
						}
					}
					// §14.2a: no session, no terminal, while a reparent is
					// recorded for this feature.
					if rerr := refuseOpenDuringReparent(ws, feature); rerr != nil {
						return rerr
					}
					if noAgent {
						fmt.Printf("cd %s\n", fp)
						return nil
					}
					return internal.WithCheckoutSessionLaunchIntent(ws, func() error {
						return internal.CheckoutFeatureDirSessionPreconditions(ws)
					}, func() error {
						fmt.Printf("Opening feature dir: %s\n", fp)
						// A feature directory is not a logical branch, so it
						// has no per-branch record; the workspace intent itself
						// remains live through the agent and shell.
						return openDirect(directOpenOpts{
							Path: fp, AgentCommand: managedCfg.AgentCommand,
						})
					})
				}

				return runCheckoutOpenResolved(ws, args, useTmux, noTmux, noAgent, cmd.Flags(), nil)
			}
			// Handle --all: tmux session with all worktrees
			if all {
				if len(args) < 1 {
					return fmt.Errorf("usage: tws open <feature> --all")
				}
				feature := args[0]
				ws, err = managedTemplateWorkspaceForFeature(ws, feature)
				if err != nil {
					return err
				}
				if gerr := internal.GuardFeatureName(ws.MetadataRoot, feature); gerr != nil {
					return gerr
				}
				resolved, resolveErr := ws.ResolveFeaturePath(feature)
				if resolveErr != nil {
					return resolveErr
				}
				featurePath := resolved
				if managed, managedErr := internal.ManagedTemplateStatePresent(resolved); managedErr != nil {
					return managedErr
				} else if managed {
					managedCfg, err := resolveManagedConfig(ws)
					if err != nil {
						return err
					}
					if err := internal.ValidateManagedOrchestratorContext(
						ws, feature, featurePath, managedCfg.AgentCommand,
					); err != nil {
						return err
					}
					if _, err := syncManagedAndLegacyInjectAll(
						cmd, ws, feature, featurePath,
						managedInjectTarget{Value: managedCfg.Config.InjectInto},
					); err != nil {
						return fmt.Errorf("managed inject sync failed: %w", err)
					}
				}
				return openAllAt(feature, featurePath, internal.ListBranchesAt(featurePath), func() error {
					return refuseOpenDuringReparent(ws, feature)
				})
			}

			// Handle --feature-dir: open the feature directory
			if featureDir {
				if len(args) < 1 {
					return fmt.Errorf("usage: tws open <feature> --feature-dir")
				}
				feature := args[0]
				ws, err = managedTemplateWorkspaceForFeature(ws, feature)
				if err != nil {
					return err
				}
				if gerr := internal.GuardFeatureName(ws.MetadataRoot, feature); gerr != nil {
					return gerr
				}
				resolved, resolveErr := ws.ResolveFeaturePath(feature)
				if resolveErr != nil {
					return resolveErr
				}
				path := resolved
				managed, managedErr := internal.ManagedTemplateStatePresent(resolved)
				if managedErr != nil {
					return managedErr
				}
				var managedCfg resolvedManagedConfig
				if managed {
					managedCfg, err = resolveManagedConfig(ws)
					if err != nil {
						return err
					}
					if err := internal.ValidateManagedOrchestratorContext(
						ws, feature, path, managedCfg.AgentCommand,
					); err != nil {
						return err
					}
				}
				if _, err := os.Stat(path); os.IsNotExist(err) {
					return fmt.Errorf("feature not found: %s", feature)
				}
				// The resolved path is authoritative for this route. Refuse
				// before the no-agent fast path and before any success prose;
				// the intent wrapper below repeats the check after publishing
				// its race-closing launch intent.
				if err := refuseExternalOpenDuringMutation(feature, path); err != nil {
					return err
				}
				if noAgent {
					fmt.Printf("cd %s\n", path)
					return nil
				}
				return withExternalSessionLaunchIntent(path, feature, nil, true, func() error {
					return refuseExternalOpenDuringMutation(feature, path)
				}, func() error {
					fmt.Printf("Opening feature dir: %s\n", path)
					// Untracked: a feature directory is not a logical branch,
					// so no long-lived direct session record is created.
					return openDirect(directOpenOpts{
						Path: path, AgentCommand: managedCfg.AgentCommand,
					})
				})
			}

			// Normal mode: open a specific worktree
			context, branch, err := resolveOpenArgs(ws, args)
			if err != nil {
				return err
			}
			ws = context.Workspace
			feature := context.Feature
			// §14.2a, after the picker has settled the identity: the exclusion
			// covers the 0-arg and 1-arg picker routes too.
			if rerr := refuseOpenDuringReparent(ws, feature); rerr != nil {
				return rerr
			}

			featurePath := context.FeaturePath
			path := filepath.Join(featurePath, "worktrees", filepath.FromSlash(branch))
			resolvedFeaturePath := context.FeaturePath
			managed, managedErr := internal.ManagedTemplateStatePresent(resolvedFeaturePath)
			if managedErr != nil {
				return managedErr
			}
			if managed {
				featurePath = resolvedFeaturePath
			}

			if _, err := os.Stat(path); os.IsNotExist(err) {
				return fmt.Errorf("worktree not found: %s", path)
			}

			// Re-sync inject files
			injectTarget := internal.ResolveInjectInto("")
			var managedCfg resolvedManagedConfig
			if managed {
				managedCfg, err = resolveManagedConfig(ws)
				if err != nil {
					return err
				}
				injectTarget = managedCfg.Config.InjectInto
				if err := syncManagedAndLegacyInject(
					cmd, ws, feature, featurePath, branch, path,
					managedInjectTarget{Value: injectTarget},
				); err != nil {
					return fmt.Errorf("managed inject sync failed: %w", err)
				}
			} else if err := internal.InjectFiles(featurePath, path, injectTarget); err != nil {
				fmt.Printf("Warning: inject sync failed: %v\n", err)
			}

			// Show unread decisions count
			unread := internal.UnreadDecisions(featurePath, branch)
			if len(unread) > 0 {
				targeted := 0
				for _, d := range unread {
					if d.To != "" {
						targeted++
					}
				}
				msg := fmt.Sprintf("  %d new decision(s)", len(unread))
				if targeted > 0 {
					msg += fmt.Sprintf(" (%d for you)", targeted)
				}
				msg += fmt.Sprintf(" (run: tws decisions show %s)", feature)
				fmt.Println(msg)
			}

			if noAgent {
				fmt.Printf("cd %s\n", path)
				fmt.Println("Run your agent manually from there.")
				return nil
			}

			// Resolve tmux preference
			tmux := useTmux
			if !cmd.Flags().Changed("tmux") && !noTmux {
				cfg := internal.LoadConfig()
				if managed {
					cfg = managedCfg.Config
				}
				if cfg.UseTmux != nil {
					tmux = *cfg.UseTmux
				}
			}
			if noTmux {
				tmux = false
			}

			if tmux {
				return openWithTmuxResolved(feature, branch, path, featurePath, managedCfg.AgentCommand, func() error {
					return refuseOpenDuringReparent(ws, feature)
				})
			}
			// Warn if there's a stale tmux session
			session := sanitizeSessionName(feature + "/" + branch)
			if sessionExists(session) {
				fmt.Printf("Warning: tmux session %q exists for this worktree.\n", session)
				fmt.Printf("  Run 'tws close %s %s' to kill it, or use --tmux to attach.\n", feature, branch)
			}
			return openDirect(directOpenOpts{
				Path:         path,
				Feature:      feature,
				Name:         branch,
				GitBranch:    resolveDirectGitBranch(featurePath, branch),
				FeaturePath:  featurePath,
				AgentCommand: managedCfg.AgentCommand,
				FinalGuard: func() error {
					return refuseOpenDuringReparent(ws, feature)
				},
			})
		},
	}

	cmd.Flags().BoolVar(&useTmux, "tmux", false, "Wrap in tmux session")
	cmd.Flags().BoolVar(&noTmux, "no-tmux", false, "Skip tmux even if configured")
	cmd.Flags().BoolVar(&noAgent, "no-agent", false, "Just print the worktree path")
	cmd.Flags().BoolVar(&featureDir, "feature-dir", false, "Open the feature directory (orchestrator mode)")
	cmd.Flags().BoolVar(&all, "all", false, "Create tmux session with windows for all worktrees")

	return cmd
}

func resolveOpenArgs(ws internal.Workspace, args []string) (resolvedFeatureContext, string, error) {
	var feature, branch string
	var err error

	switch len(args) {
	case 2:
		context, err := resolveFeatureContext(ws, args[0])
		return context, args[1], err
	case 1:
		feature = args[0]
		context, err := resolveFeatureContext(ws, feature)
		if err != nil {
			return resolvedFeatureContext{}, "", err
		}
		branches := internal.ListBranchesAt(context.FeaturePath)
		if len(branches) == 0 {
			return resolvedFeatureContext{}, "", fmt.Errorf("no branches found for feature: %s", feature)
		}
		branch, err = pick("Select branch:", branches)
		if err != nil {
			return resolvedFeatureContext{}, "", err
		}
		return context, branch, nil
	case 0:
		executionWS, resolveErr := managedTemplateExecutionWorkspace(ws)
		if resolveErr != nil {
			return resolvedFeatureContext{}, "", resolveErr
		}
		features, listErr := executionWS.ListFeaturesResolved()
		if listErr != nil {
			return resolvedFeatureContext{}, "", listErr
		}
		if len(features) == 0 {
			return resolvedFeatureContext{}, "", fmt.Errorf("no features found. Use 'tws add <feature>' to create one")
		}
		feature, err = pick("Select feature:", features)
		if err != nil {
			return resolvedFeatureContext{}, "", err
		}
		context, err := resolveFeatureContext(executionWS, feature)
		if err != nil {
			return resolvedFeatureContext{}, "", err
		}
		branches := internal.ListBranchesAt(context.FeaturePath)
		if len(branches) == 0 {
			return resolvedFeatureContext{}, "", fmt.Errorf("no branches found for feature: %s", feature)
		}
		branch, err = pick("Select branch:", branches)
		if err != nil {
			return resolvedFeatureContext{}, "", err
		}
		return context, branch, nil
	}
	return resolvedFeatureContext{}, "", fmt.Errorf("unexpected args")
}

// openAll creates a tmux session with the feature dir as the first window
// and one window per active worktree.
// ExternalSessionLaunchIntentHook is a test-only seam after a tmux/all/feature
// launch intent is durable and before the final feature-mutation check.
var ExternalSessionLaunchIntentHook func() error

func withExternalSessionLaunchIntent(featurePath, feature string, names []string, featureWide bool, finalGuard, action func() error) (err error) {
	token, err := internal.CreateExternalSessionIntent(featurePath, feature, names, featureWide)
	if err != nil {
		return err
	}
	defer func() {
		err = errors.Join(err, internal.RemoveOwnedExternalSessionIntent(featurePath, token))
	}()
	if ExternalSessionLaunchIntentHook != nil {
		if err := ExternalSessionLaunchIntentHook(); err != nil {
			return err
		}
	}
	if finalGuard != nil {
		if err := finalGuard(); err != nil {
			return err
		}
	}
	if action == nil {
		return nil
	}
	return action()
}

func openAll(feature, featurePath string, finalGuard func() error) error {
	return openAllAt(feature, featurePath, internal.ListBranchesAt(featurePath), finalGuard)
}

func openAllAt(feature, featurePath string, branches []string, finalGuard func() error) error {
	if _, err := os.Stat(featurePath); os.IsNotExist(err) {
		return fmt.Errorf("feature not found: %s", feature)
	}
	return withExternalSessionLaunchIntent(featurePath, feature, nil, true, finalGuard, func() error {
		if _, err := exec.LookPath("tmux"); err != nil {
			return fmt.Errorf("required tool %q not found in PATH", "tmux")
		}
		session := sanitizeSessionName(feature)
		if sessionExists(session) {
			fmt.Printf("Attaching to existing session: %s\n", session)
			return internal.Run("tmux", "attach", "-t", session)
		}

		fmt.Printf("Creating tmux session: %s\n", session)
		if err := internal.Run("tmux", "new-session", "-d", "-s", session, "-c", featurePath, "-n", "orchestrator"); err != nil {
			return err
		}

		for _, branch := range branches {
			wtPath := filepath.Join(featurePath, "worktrees", filepath.FromSlash(branch))
			if _, err := os.Stat(wtPath); os.IsNotExist(err) {
				continue
			}
			windowName := sanitizeSessionName(branch)
			_ = internal.RunSilent("tmux", "new-window", "-t", session, "-n", windowName, "-c", wtPath)
		}
		_ = internal.RunSilent("tmux", "select-window", "-t", session+":orchestrator")
		return internal.Run("tmux", "attach", "-t", session)
	})
}

func openWithTmux(feature, branch, path, featurePath string, finalGuard func() error) error {
	return openWithTmuxResolved(feature, branch, path, featurePath, "", finalGuard)
}

func openWithTmuxResolved(
	feature, branch, path, featurePath, agentCommand string,
	finalGuard func() error,
) error {
	return withExternalSessionLaunchIntent(featurePath, feature, []string{branch}, false, finalGuard, func() error {
		if _, err := exec.LookPath("tmux"); err != nil {
			return fmt.Errorf("required tool %q not found in PATH", "tmux")
		}
		session := sanitizeSessionName(feature + "/" + branch)
		if sessionExists(session) {
			fmt.Printf("Attaching to existing session: %s\n", session)
			return internal.Run("tmux", "attach", "-t", session)
		}

		agentCmd := agentCommand
		if agentCmd == "" {
			cfg := internal.LoadConfig()
			agentCmd = cfg.GetAgentCommand()
		}
		if isClaudeAgent(agentCmd) && hasClaudeSession(path) {
			agentCmd += " -c"
		}

		fmt.Printf("Creating tmux session: %s\n", session)
		if err := internal.Run("tmux", "new-session", "-d", "-s", session, "-c", path); err != nil {
			return err
		}
		fmt.Printf("Running: %s\n", agentCmd)
		if err := internal.Run("tmux", "send-keys", "-t", session, agentCmd, "Enter"); err != nil {
			return err
		}
		return internal.Run("tmux", "attach", "-t", session)
	})
}

func sessionExists(name string) bool {
	cmd := exec.Command("tmux", "has-session", "-t", name)
	err := cmd.Run()
	return err == nil
}

func sanitizeSessionName(s string) string {
	return internal.SanitizeTmuxName(s)
}

func isClaudeAgent(cmd string) bool {
	fields := strings.Fields(cmd)
	if len(fields) == 0 {
		return false
	}
	base := fields[0]
	return base == "claude" || base == "claude-dev" || base == "cc"
}

func hasClaudeSession(workdir string) bool {
	home, err := os.UserHomeDir()
	if err != nil {
		return false
	}

	absPath, err := filepath.Abs(workdir)
	if err != nil {
		return false
	}

	encoded := strings.ReplaceAll(absPath, string(filepath.Separator), "-")
	projectDir := filepath.Join(home, ".claude", "projects", encoded)

	info, err := os.Stat(projectDir)
	if err != nil {
		return false
	}
	return info.IsDir()
}

package cli

import (
	"fmt"
	"sort"

	"github.com/jdbencardinop/tesseraworkspaces/internal"
)

func runCheckoutOpen(ws internal.Workspace, args []string, useTmux, noTmux, noAgent bool, cmdFlag interface{ Changed(string) bool }) error {
	return runCheckoutOpenResolved(ws, args, useTmux, noTmux, noAgent, cmdFlag, nil)
}

func runCheckoutOpenResolved(
	ws internal.Workspace,
	args []string,
	useTmux, noTmux, noAgent bool,
	cmdFlag interface{ Changed(string) bool },
	managedCfg *resolvedManagedConfig,
) error {
	// Guarded at the top: resolveCheckoutOpenArgs already resolves feature
	// paths and loads stacks for a named feature.
	if len(args) >= 1 {
		if err := internal.GuardFeatureName(ws.MetadataRoot, args[0]); err != nil {
			return err
		}
	}
	feature, name, err := resolveCheckoutOpenArgs(ws, args)
	if err != nil {
		return err
	}
	featurePath, err := ws.ResolveFeaturePath(feature)
	if err != nil {
		return err
	}
	managed, err := internal.ManagedTemplateStatePresent(featurePath)
	if err != nil {
		return err
	}
	cfg := internal.LoadConfig()
	target := managedInjectTarget{Value: internal.ResolveInjectInto("")}
	if managed {
		if managedCfg == nil {
			resolved, err := resolveManagedConfig(ws)
			if err != nil {
				return err
			}
			managedCfg = &resolved
		}
		cfg = managedCfg.Config
		target = managedInjectTarget{Value: cfg.InjectInto}
		if err := internal.ValidateManagedCheckoutContextResolved(
			ws, feature, featurePath, managedCfg.AgentCommand,
			target.Value, target.Explicit,
		); err != nil {
			return err
		}
	}
	if noAgent {
		fmt.Println(ws.RepoRoot)
		return nil
	}
	stack, err := internal.LoadStack(featurePath)
	if err != nil {
		return err
	}
	entry := internal.GetBranch(stack, name)
	if entry.Name == "" {
		return fmt.Errorf("branch %q not found in feature %q", name, feature)
	}
	command := internal.CheckoutSessionAgentCommand(cfg.GetAgentCommand(), ws.RepoRoot)
	tmux := useTmux
	if !cmdFlag.Changed("tmux") && !noTmux && cfg.UseTmux != nil {
		tmux = *cfg.UseTmux
	}
	if noTmux {
		tmux = false
	}
	if tmux {
		return internal.OpenCheckoutTmux(ws, feature, entry, command, nil, target.Value)
	}
	return internal.OpenCheckoutDirect(ws, feature, entry, command, nil, nil, target.Value)
}

func resolveCheckoutOpenArgs(ws internal.Workspace, args []string) (string, string, error) {
	switch len(args) {
	case 2:
		return args[0], args[1], nil
	case 1:
		names, err := checkoutActiveNames(ws, args[0])
		if err != nil {
			return "", "", err
		}
		if len(names) == 1 {
			return args[0], names[0], nil
		}
		name, err := pick("Select branch:", names)
		return args[0], name, err
	case 0:
		features, err := ws.ListFeaturesResolved()
		if err != nil {
			return "", "", err
		}
		if len(features) == 0 {
			return "", "", fmt.Errorf("no features found")
		}
		feature := features[0]
		if len(features) > 1 {
			feature, err = pick("Select feature:", features)
			if err != nil {
				return "", "", err
			}
		}
		names, err := checkoutActiveNames(ws, feature)
		if err != nil {
			return "", "", err
		}
		if len(names) == 1 {
			return feature, names[0], nil
		}
		name, err := pick("Select branch:", names)
		return feature, name, err
	default:
		return "", "", fmt.Errorf("too many arguments")
	}
}
func checkoutActiveNames(ws internal.Workspace, feature string) ([]string, error) {
	path, err := ws.ResolveFeaturePath(feature)
	if err != nil {
		return nil, err
	}
	stack, err := internal.LoadStack(path)
	if err != nil {
		return nil, err
	}
	var names []string
	for _, entry := range stack.Branches {
		if !entry.Archived && entry.Repo == "" {
			names = append(names, entry.Name)
		}
	}
	sort.Strings(names)
	if len(names) == 0 {
		return nil, fmt.Errorf("no active branches in feature %q", feature)
	}
	return names, nil
}

package cli

import (
	"errors"
	"fmt"
	"os"
	"os/exec"
	"path/filepath"
	"strings"

	"github.com/jdbencardinop/tesseraworkspaces/internal"
	"github.com/spf13/cobra"
)

var renameBranchExternalStepHook func(step string) error

func renameCmd() *cobra.Command {
	cmd := &cobra.Command{
		Use:   "rename",
		Short: "Rename a feature or branch",
	}

	cmd.AddCommand(renameFeatureCmd())
	cmd.AddCommand(renameBranchCmd())

	return cmd
}

func renameFeatureCmd() *cobra.Command {
	return &cobra.Command{
		Use:   "feature <old-name> <new-name>",
		Short: "Rename a feature",
		Args:  cobra.ExactArgs(2),
		RunE: func(cmd *cobra.Command, args []string) (retErr error) {
			oldName := args[0]
			newName := args[1]

			ws, err := internal.RequireWorkspace()
			if err != nil {
				return err
			}
			context, err := resolveFeatureContext(ws, oldName)
			if err != nil {
				return err
			}
			ws = context.Workspace
			root := ws.MetadataRoot

			oldPath := context.FeaturePath
			newPath := ws.FeaturePath(newName)

			if _, err := os.Stat(oldPath); os.IsNotExist(err) {
				return fmt.Errorf("feature not found: %s", oldName)
			}
			lifecycle, err := internal.AcquireManagedFeatureLifecycleLock(oldPath)
			if err != nil {
				return err
			}
			defer func() { retErr = errors.Join(retErr, lifecycle.Release()) }()
			managed, err := internal.ManagedTemplateStatePresent(oldPath)
			if err != nil {
				return err
			}
			managedReservation, err := acquireManagedFeatureRenameReservation(ws, oldName, oldPath, managed)
			if err != nil {
				return err
			}
			defer func() { retErr = errors.Join(retErr, managedReservation.Release()) }()

			// One locked read validates both names and stages the registry
			// rewrite. It runs before the destination-collision check so a
			// registered space directory reports the space conflict rather
			// than "feature already exists". With no spaces.yaml this is a
			// true no-op: no lock file, no registry file, nothing created.
			tx, err := internal.BeginSpacesFeatureRename(root, oldName, newName, oldPath, newPath)
			if err != nil {
				return err
			}
			defer func() { retErr = errors.Join(retErr, tx.Release()) }()

			if _, err := os.Stat(newPath); err == nil {
				return fmt.Errorf("feature already exists: %s", newName)
			}

			// External direct session records must not silently relocate: a
			// whole-directory rename would move every record so its recorded
			// feature and its <branch-id> hash disagree with its location.
			// Checkout mode never writes or reads them.
			if ws.Mode == internal.ModeExternal {
				targets, terr := directRecordTargetsForFeature(oldPath)
				if terr != nil {
					return terr
				}
				if gerr := guardDirectRecords(cmd.OutOrStdout(), oldPath, "rename feature", oldName, targets); gerr != nil {
					return gerr
				}
			}

			if err := os.Rename(oldPath, newPath); err != nil {
				return fmt.Errorf("error renaming: %w", err)
			}
			managedReservation.Moved(newName, newPath)

			if commitErr := tx.Commit(); commitErr != nil {
				if rollbackErr := os.Rename(newPath, oldPath); rollbackErr != nil {
					return errors.Join(commitErr, fmt.Errorf(
						"rollback failed: feature directory is now %s on disk while %s still refers to %q; repair with 'tws space remove' and 'tws space add': %w",
						newPath, internal.SpacesFilePath(root), oldName, rollbackErr))
				}
				managedReservation.Moved(oldName, oldPath)
				return commitErr
			}

			fmt.Printf("Renamed feature: %s → %s\n", oldName, newName)
			return nil
		},
	}
}

func renameBranchCmd() *cobra.Command {
	return &cobra.Command{
		Use:   "branch <feature> <old-name> <new-name>",
		Short: "Rename a branch within a feature",
		Args:  cobra.ExactArgs(3),
		ValidArgsFunction: func(cmd *cobra.Command, args []string, toComplete string) ([]string, cobra.ShellCompDirective) {
			switch len(args) {
			case 0:
				return managedCompletionFeatures(), cobra.ShellCompDirectiveNoFileComp
			case 1:
				return managedCompletionBranches(args[0]), cobra.ShellCompDirectiveNoFileComp
			default:
				return nil, cobra.ShellCompDirectiveNoFileComp
			}
		},
		RunE: func(cmd *cobra.Command, args []string) error {
			internal.RequireTool("git")

			feature := args[0]
			oldName := args[1]
			newName := args[2]

			ws, err := internal.RequireWorkspace()
			if err != nil {
				return err
			}
			context, err := resolveFeatureContext(ws, feature)
			if err != nil {
				return err
			}
			ws = context.Workspace

			if ws.Mode == internal.ModeCheckout {
				return renameBranchCheckoutAt(ws, feature, context.FeaturePath, oldName, newName)
			}
			return renameBranchExternalAt(ws, feature, context.FeaturePath, oldName, newName)
		},
	}
}

func renameBranchCheckout(ws internal.Workspace, feature, oldName, newName string) error {
	featurePath, err := ws.ResolveFeaturePath(feature)
	if err != nil {
		return err
	}
	return renameBranchCheckoutAt(ws, feature, featurePath, oldName, newName)
}

// renameBranchCheckout renames a branch in checkout mode.
// Uses entry.GitBranch() for git operations (honoring prefixes).
// Short Name is the metadata identity; git branch may have a prefix.
// Metadata is updated only after git succeeds; rolled back if SaveStack fails.
func renameBranchCheckoutAt(ws internal.Workspace, feature, featurePath, oldName, newName string) (retErr error) {
	if err := internal.GuardFeatureName(ws.MetadataRoot, feature); err != nil {
		return err
	}
	lifecycle, err := internal.AcquireManagedFeatureLifecycleLock(featurePath)
	if err != nil {
		return err
	}
	defer func() { retErr = errors.Join(retErr, lifecycle.Release()) }()
	managed, err := internal.ManagedTemplateStatePresent(featurePath)
	if err != nil {
		return err
	}
	reservation, err := acquireManagedFeatureRenameReservation(ws, feature, featurePath, managed)
	if err != nil {
		return err
	}
	defer func() { retErr = errors.Join(retErr, reservation.Release()) }()
	cfg := internal.LoadConfigForRepo(ws.RepoRoot)
	if managed {
		cfg, err = internal.LoadConfigForRepoE(ws.RepoRoot)
		if err != nil {
			return err
		}
		if err := internal.ValidateManagedCheckoutContextResolved(
			ws, feature, featurePath, cfg.GetAgentCommand(), cfg.InjectInto, false,
		); err != nil {
			return err
		}
		if err := internal.ValidateManagedOrchestratorContext(
			ws, feature, featurePath, cfg.GetAgentCommand(),
		); err != nil {
			return err
		}
	}

	stack, err := internal.LoadStack(featurePath)
	if err != nil {
		return fmt.Errorf("no stack.yaml found for feature: %s", feature)
	}

	entry := internal.GetBranch(stack, oldName)
	if entry.Name == "" {
		return fmt.Errorf("branch %q not found in stack", oldName)
	}

	oldGitBranch := entry.GitBranch()

	// Compute new git branch name: preserve prefix structure.
	newGitBranch := newName
	if cfg.BranchPrefix != "" {
		newGitBranch = cfg.BranchPrefix + newName
	}

	// Git rename using GitBranch() (the actual branch name, possibly prefixed).
	if err := internal.RunDir(ws.RepoRoot, "git", "branch", "-m", oldGitBranch, newGitBranch); err != nil {
		return fmt.Errorf("error renaming git branch %s -> %s: %w", oldGitBranch, newGitBranch, err)
	}

	// Now mutate metadata (git succeeded).
	internal.RenameBranch(&stack, oldName, newName)
	// Update Branch field if the new git branch differs from the new name.
	for i := range stack.Branches {
		if stack.Branches[i].Name == newName {
			if newGitBranch != newName {
				stack.Branches[i].Branch = newGitBranch
			} else {
				stack.Branches[i].Branch = ""
			}
			break
		}
	}

	if err := internal.SaveStack(featurePath, stack); err != nil {
		if rollbackErr := internal.RunSilentDir(ws.RepoRoot, "git", "branch", "-m", newGitBranch, oldGitBranch); rollbackErr != nil {
			return fmt.Errorf("error saving stack: %w; rollback of git branch also failed: %v", err, rollbackErr)
		}
		return fmt.Errorf("error saving stack (git branch rolled back): %w", err)
	}

	// Update decisions.yaml branch references.
	decisions, loadErr := internal.LoadDecisions(featurePath)
	if loadErr == nil {
		for i := range decisions.Entries {
			if decisions.Entries[i].Branch == oldName {
				decisions.Entries[i].Branch = newName
			}
		}
		_ = internal.SaveDecisions(featurePath, decisions)
	}

	fmt.Printf("Renamed branch: %s → %s (git: %s → %s, in feature %s)\n", oldName, newName, oldGitBranch, newGitBranch, feature)
	return nil
}

func renameBranchExternal(feature, oldName, newName string) error {
	ws, err := internal.RequireWorkspace()
	if err != nil {
		return err
	}
	context, err := resolveFeatureContext(ws, feature)
	if err != nil {
		return err
	}
	return renameBranchExternalAt(context.Workspace, feature, context.FeaturePath, oldName, newName)
}

// renameBranchExternal renames a branch in external mode.
// Uses entry.GitBranch() for git operations.
func renameBranchExternalAt(ws internal.Workspace, feature, featurePath, oldName, newName string) (retErr error) {
	if err := internal.GuardFeatureName(ws.MetadataRoot, feature); err != nil {
		return err
	}
	lifecycle, err := internal.AcquireManagedFeatureLifecycleLock(featurePath)
	if err != nil {
		return err
	}
	defer func() { retErr = errors.Join(retErr, lifecycle.Release()) }()
	managed, err := internal.ManagedTemplateStatePresent(featurePath)
	if err != nil {
		return err
	}
	reservation, err := acquireManagedFeatureRenameReservation(ws, feature, featurePath, managed)
	if err != nil {
		return err
	}
	defer func() { retErr = errors.Join(retErr, reservation.Release()) }()
	cfg := internal.LoadConfigForRepo(ws.RepoRoot)
	if managed {
		cfg, err = internal.LoadConfigForRepoE(ws.RepoRoot)
		if err != nil {
			return err
		}
		if err := internal.ValidateManagedCheckoutContextResolved(
			ws, feature, featurePath, cfg.GetAgentCommand(), cfg.InjectInto, false,
		); err != nil {
			return err
		}
		if err := internal.ValidateManagedOrchestratorContext(
			ws, feature, featurePath, cfg.GetAgentCommand(),
		); err != nil {
			return err
		}
	}

	stack, err := internal.LoadStack(featurePath)
	if err != nil {
		return fmt.Errorf("no stack.yaml found for feature: %s", feature)
	}

	if !internal.HasBranch(stack, oldName) {
		return fmt.Errorf("branch %q not found in stack", oldName)
	}

	// Renaming a branch changes <branch-id>, name, git_branch, and the
	// worktree path, so no record may survive the rewrite.
	if gerr := guardDirectRecords(os.Stdout, featurePath, "rename branch", feature+"/"+oldName,
		directRecordTargetForBranch(feature, oldName)); gerr != nil {
		return gerr
	}

	entry := internal.GetBranch(stack, oldName)
	oldGitBranch := entry.GitBranch()

	// Compute new git branch name preserving prefix.
	newGitBranch := newName
	if cfg.BranchPrefix != "" {
		newGitBranch = cfg.BranchPrefix + newName
	}

	oldPath := filepath.Join(featurePath, "worktrees", filepath.FromSlash(oldName))
	newPath := filepath.Join(featurePath, "worktrees", filepath.FromSlash(newName))
	materialized := false

	if _, err := os.Stat(oldPath); err == nil {
		if residue, err := internal.ManagedTemplateRecoveryResidue(oldPath); err != nil {
			return err
		} else if residue != "" {
			return fmt.Errorf("managed template recovery evidence exists at %s; resolve it before renaming the branch", residue)
		}
		materialized = true
		verifiedPath, resolveErr := internal.ResolveInjectWorktree(featurePath, oldName)
		if resolveErr != nil {
			return fmt.Errorf("resolving selected worktree %q: %w", oldName, resolveErr)
		}
		oldPath = verifiedPath
	} else if !os.IsNotExist(err) {
		return fmt.Errorf("checking selected worktree %s: %w", oldPath, err)
	}
	targetRepo, err := resolveBranchRenameRepo(ws, entry, oldPath, materialized)
	if err != nil {
		return err
	}
	var oldBranchOID string
	if managed {
		if oldName != newName && internal.HasBranch(stack, newName) {
			return fmt.Errorf("destination branch name %q is already registered in stack", newName)
		}
		var oldExists bool
		var branchErr error
		oldBranchOID, oldExists, branchErr = localGitBranchOID(targetRepo, oldGitBranch)
		if branchErr != nil {
			return branchErr
		}
		if !oldExists {
			return fmt.Errorf("stored Git branch %q does not exist in %s", oldGitBranch, targetRepo)
		}
		if newGitBranch != oldGitBranch {
			if _, newExists, branchErr := localGitBranchOID(targetRepo, newGitBranch); branchErr != nil {
				return branchErr
			} else if newExists {
				return fmt.Errorf("destination Git branch %q already exists in %s", newGitBranch, targetRepo)
			}
		}
		if materialized {
			if overlap, overlapErr := managedRenamePathsOverlap(oldPath, newPath); overlapErr != nil {
				return overlapErr
			} else if overlap {
				return fmt.Errorf(
					"managed worktree rename paths overlap as ancestor/descendant paths: %s and %s",
					oldPath, newPath,
				)
			}
			if _, pathErr := os.Lstat(newPath); pathErr == nil {
				return fmt.Errorf("destination worktree path already exists: %s", newPath)
			} else if !errors.Is(pathErr, os.ErrNotExist) {
				return fmt.Errorf("checking destination worktree path %s: %w", newPath, pathErr)
			}
		}
	}
	var retirement *preparedManagedWorktreeRetirement
	if managed {
		retirement, err = prepareManagedWorktreeLinkRetirement(
			ws, feature, featurePath, oldName,
		)
		if err != nil {
			return fmt.Errorf("preparing managed link ownership retirement for branch rename: %w", err)
		}
	}
	var recoveryContext *managedRenameRecoveryContext
	if managed {
		recoveryContext, err = newManagedRenameRecoveryContext(
			featurePath, feature, targetRepo,
			oldName, newName, oldGitBranch, newGitBranch,
			oldPath, newPath, oldBranchOID,
		)
		if err != nil {
			return err
		}
	}
	stackCompletedStages := []string{"branch-renamed"}
	stackPendingStages := []string{"stack-publication"}
	if materialized {
		stackCompletedStages = []string{
			"old-worktree-removed", "branch-renamed",
			"new-worktree-created", "link-retirement",
		}
		stackPendingStages = []string{"stack-publication", "managed-reinjection"}
	}

	if materialized {
		// Active worktree: remove, rename branch, re-add
		if err := internal.RunDir(targetRepo, "git", "worktree", "remove", "--force", oldPath); err != nil {
			return fmt.Errorf("error removing worktree: %w", err)
		}
		if newGitBranch != oldGitBranch {
			if err := runRenameBranchExternalStep("before-branch-rename", func() error {
				return internal.RunDir(targetRepo, "git", "branch", "-m", oldGitBranch, newGitBranch)
			}); err != nil {
				if managed {
					rollbackErr := rollbackManagedMaterializedBranchRename(
						retirement, recoveryContext, targetRepo,
						oldPath, newPath, oldGitBranch, newGitBranch, oldBranchOID,
					)
					return errors.Join(fmt.Errorf("error renaming git branch: %w", err), rollbackErr)
				}
				restoreErr := internal.RunDir(targetRepo, "git", "worktree", "add", oldPath, oldGitBranch)
				return errors.Join(fmt.Errorf("error renaming git branch: %w", err),
					wrapRenameRollbackError("restoring original worktree", restoreErr))
			}
		}
		if err := runRenameBranchExternalStep("before-new-worktree-add", func() error {
			return internal.RunDir(targetRepo, "git", "worktree", "add", newPath, newGitBranch)
		}); err != nil {
			if managed {
				rollbackErr := rollbackManagedMaterializedBranchRename(
					retirement, recoveryContext, targetRepo,
					oldPath, newPath, oldGitBranch, newGitBranch, oldBranchOID,
				)
				return errors.Join(fmt.Errorf("error creating new worktree: %w", err), rollbackErr)
			}
			renameBackErr := internal.RunDir(targetRepo, "git", "branch", "-m", newGitBranch, oldGitBranch)
			restoreErr := internal.RunDir(targetRepo, "git", "worktree", "add", oldPath, oldGitBranch)
			return errors.Join(fmt.Errorf("error creating new worktree: %w", err),
				wrapRenameRollbackError("restoring original branch name", renameBackErr),
				wrapRenameRollbackError("restoring original worktree", restoreErr))
		}
		if err := retirement.publishAfterRemoval(); err != nil {
			if managed {
				return managedRenamePartialOutcome(
					recoveryContext, "retirement-publication",
					[]string{"old-worktree-removed", "branch-renamed", "new-worktree-created"},
					[]string{"link-retirement", "stack-publication", "managed-reinjection"},
					fmt.Errorf("publishing managed link ownership retirement after completed branch Git effects: %w", err),
				)
			}
			return fmt.Errorf("publishing managed link ownership retirement after completed branch Git effects: %w", err)
		}

	} else {
		// Archived: just rename the git branch
		if err := internal.RunDir(targetRepo, "git", "branch", "-m", oldGitBranch, newGitBranch); err != nil {
			return fmt.Errorf("error renaming git branch: %w", err)
		}
	}

	// Now mutate metadata (git succeeded).
	internal.RenameBranch(&stack, oldName, newName)
	for i := range stack.Branches {
		if stack.Branches[i].Name == newName {
			if newGitBranch != newName {
				stack.Branches[i].Branch = newGitBranch
			} else {
				stack.Branches[i].Branch = ""
			}
			break
		}
	}

	if managed {
		if err := runRenameBranchExternalStep("before-stack-publication", func() error { return nil }); err != nil {
			return managedRenamePartialOutcome(
				recoveryContext, "stack-publication",
				stackCompletedStages, stackPendingStages,
				err,
			)
		}
		if err := internal.SaveStackAtomic(featurePath, stack); err != nil {
			return managedRenamePartialOutcome(
				recoveryContext, "stack-publication",
				stackCompletedStages, stackPendingStages,
				fmt.Errorf("error saving stack: %w", err),
			)
		}
	} else if err := internal.SaveStack(featurePath, stack); err != nil {
		return fmt.Errorf("error saving stack: %w", err)
	}
	if materialized {
		target := cfg.InjectInto
		managedPresent, managedErr := internal.ManagedTemplateStatePresent(featurePath)
		if managedErr != nil {
			if managed {
				return managedRenamePartialOutcome(
					recoveryContext, "managed-context-validation",
					[]string{"old-worktree-removed", "branch-renamed", "new-worktree-created", "link-retirement", "stack-publication"},
					[]string{"managed-reinjection"}, managedErr,
				)
			}
			return managedErr
		}
		if managed && !managedPresent {
			return managedRenamePartialOutcome(
				recoveryContext, "managed-context-validation",
				[]string{"old-worktree-removed", "branch-renamed", "new-worktree-created", "link-retirement", "stack-publication"},
				[]string{"managed-reinjection"},
				errors.New("managed ownership state disappeared after branch Git effects"),
			)
		}
		if managedPresent {
			if err := syncManagedAndLegacyInjectWithLifecycle(
				nil, ws, feature, featurePath, newName, newPath,
				managedInjectTarget{Value: target}, lifecycle, reservation,
			); err != nil {
				if managed {
					return managedRenamePartialOutcome(
						recoveryContext, "managed-reinjection",
						[]string{"old-worktree-removed", "branch-renamed", "new-worktree-created", "link-retirement", "stack-publication"},
						[]string{"managed-reinjection"},
						fmt.Errorf("managed inject failed after branch rename: %w", err),
					)
				}
				return fmt.Errorf("managed inject failed after branch rename: %w", err)
			}
		} else if injectErr := internal.InjectFiles(featurePath, newPath, target); injectErr != nil {
			fmt.Printf("Warning: inject failed: %v\n", injectErr)
		}
	}

	// Kill stale tmux session
	oldSession := sanitizeSessionName(feature + "/" + oldName)
	if sessionExists(oldSession) {
		_ = internal.RunSilent("tmux", "kill-session", "-t", oldSession)
	}

	// Update decisions.yaml branch references
	decisions, loadErr := internal.LoadDecisions(featurePath)
	if loadErr == nil {
		for i := range decisions.Entries {
			if decisions.Entries[i].Branch == oldName {
				decisions.Entries[i].Branch = newName
			}
		}
		_ = internal.SaveDecisions(featurePath, decisions)
	}

	fmt.Printf("Renamed branch: %s → %s (git: %s → %s, in feature %s)\n", oldName, newName, oldGitBranch, newGitBranch, feature)
	return nil
}

func resolveBranchRenameRepo(
	ws internal.Workspace,
	entry internal.StackEntry,
	materializedPath string,
	materialized bool,
) (string, error) {
	repoPath := ws.RepoRoot
	if entry.Repo != "" {
		repoPath = entry.Repo
	}
	targetRepo, err := internal.MainRepoRootIn(repoPath)
	if err != nil {
		return "", fmt.Errorf("resolving repository for stack entry %q from %s: %w",
			entry.Name, repoPath, err)
	}
	if !materialized {
		return targetRepo, nil
	}
	actualRepo, err := internal.MainRepoRootIn(materializedPath)
	if err != nil {
		return "", fmt.Errorf("resolving repository for materialized stack entry %q: %w", entry.Name, err)
	}
	if !sameResolvedRepoRoot(targetRepo, actualRepo) {
		return "", fmt.Errorf("stack entry %q records repository %s but its worktree belongs to %s",
			entry.Name, targetRepo, actualRepo)
	}
	return targetRepo, nil
}

func sameResolvedRepoRoot(a, b string) bool {
	resolve := func(path string) string {
		if evaluated, err := filepath.EvalSymlinks(path); err == nil {
			return filepath.Clean(evaluated)
		}
		absolute, err := filepath.Abs(path)
		if err != nil {
			return filepath.Clean(path)
		}
		return filepath.Clean(absolute)
	}
	return resolve(a) == resolve(b)
}

func managedRenamePathsOverlap(a, b string) (bool, error) {
	absolute := func(path string) (string, error) {
		value, err := filepath.Abs(path)
		if err != nil {
			return "", err
		}
		return filepath.Clean(value), nil
	}
	a, err := absolute(a)
	if err != nil {
		return false, err
	}
	b, err = absolute(b)
	if err != nil {
		return false, err
	}
	if a == b {
		return true, nil
	}
	isDescendant := func(parent, child string) (bool, error) {
		relative, err := filepath.Rel(parent, child)
		if err != nil {
			return false, err
		}
		return relative != "." && relative != ".." &&
			!strings.HasPrefix(relative, ".."+string(filepath.Separator)), nil
	}
	if descendant, err := isDescendant(a, b); err != nil || descendant {
		return descendant, err
	}
	if descendant, err := isDescendant(b, a); err != nil || descendant {
		return descendant, err
	}

	oldInfo, err := os.Stat(a)
	if err != nil {
		return false, fmt.Errorf("reading original worktree identity %s: %w", a, err)
	}
	nearestExisting := func(path string) (os.FileInfo, int, error) {
		missingComponents := 0
		for {
			info, statErr := os.Stat(path)
			if statErr == nil {
				return info, missingComponents, nil
			}
			if !errors.Is(statErr, os.ErrNotExist) {
				return nil, 0, statErr
			}
			parent := filepath.Dir(path)
			if parent == path {
				return nil, 0, fmt.Errorf("no existing ancestor for %s", path)
			}
			path = parent
			missingComponents++
		}
	}
	newAncestorInfo, missing, err := nearestExisting(b)
	if err != nil {
		return false, fmt.Errorf("resolving destination worktree ancestry %s: %w", b, err)
	}
	if os.SameFile(oldInfo, newAncestorInfo) {
		return true, nil
	}
	if missing != 0 {
		return false, nil
	}
	for current := a; ; current = filepath.Dir(current) {
		info, statErr := os.Stat(current)
		if statErr != nil {
			return false, fmt.Errorf("reading original worktree ancestry %s: %w", current, statErr)
		}
		if os.SameFile(info, newAncestorInfo) {
			return true, nil
		}
		parent := filepath.Dir(current)
		if parent == current {
			break
		}
	}
	return false, nil
}

func runRenameBranchExternalStep(step string, run func() error) error {
	if renameBranchExternalStepHook != nil {
		if err := renameBranchExternalStepHook(step); err != nil {
			return err
		}
	}
	return run()
}

func localGitBranchOID(repoRoot, branch string) (string, bool, error) {
	check := exec.Command("git", "-C", repoRoot, "check-ref-format", "--branch", branch)
	if output, err := check.CombinedOutput(); err != nil {
		return "", false, fmt.Errorf("validating Git branch %q: %s", branch,
			strings.TrimSpace(string(output)))
	}
	ref := "refs/heads/" + branch
	cmd := exec.Command("git", "-C", repoRoot, "show-ref", "--verify", "--quiet", ref)
	err := cmd.Run()
	if err == nil {
		resolve := exec.Command("git", "-C", repoRoot, "rev-parse", "--verify", ref+"^{commit}")
		output, resolveErr := resolve.Output()
		if resolveErr != nil {
			return "", false, fmt.Errorf("resolving Git branch %q after presence check: %w", branch, resolveErr)
		}
		return strings.TrimSpace(string(output)), true, nil
	}
	var exitErr *exec.ExitError
	if errors.As(err, &exitErr) && exitErr.ExitCode() == 1 {
		return "", false, nil
	}
	return "", false, fmt.Errorf("checking Git branch %q: %w", branch, err)
}

func verifyManagedRenameRollbackWorktree(
	targetRepo, oldPath, oldGitBranch, expectedOID string,
) error {
	actualRepo, err := internal.MainRepoRootIn(oldPath)
	if err != nil {
		return err
	}
	if !sameResolvedRepoRoot(actualRepo, targetRepo) {
		return fmt.Errorf("restored worktree belongs to %s, not %s", actualRepo, targetRepo)
	}
	branchCmd := exec.Command("git", "-C", oldPath, "symbolic-ref", "--short", "HEAD")
	branchOutput, err := branchCmd.Output()
	if err != nil {
		return fmt.Errorf("reading restored worktree branch: %w", err)
	}
	if branch := strings.TrimSpace(string(branchOutput)); branch != oldGitBranch {
		return fmt.Errorf("restored worktree is on branch %q, not %q", branch, oldGitBranch)
	}
	headCmd := exec.Command("git", "-C", oldPath, "rev-parse", "HEAD")
	headOutput, err := headCmd.Output()
	if err != nil {
		return fmt.Errorf("reading restored worktree commit: %w", err)
	}
	if head := strings.TrimSpace(string(headOutput)); head != expectedOID {
		return fmt.Errorf("restored worktree commit is %s, not %s", head, expectedOID)
	}
	return nil
}

type managedRenameRecoveryContext struct {
	featurePath string
	feature     string
	evidence    internal.ManagedTemplateBranchRenameRecoveryEvidence
}

func newManagedRenameRecoveryContext(
	featurePath, feature, targetRepo,
	oldName, newName, oldGitBranch, newGitBranch,
	oldPath, newPath, expectedOID string,
) (*managedRenameRecoveryContext, error) {
	stackPreimage, err := os.ReadFile(internal.StackPath(featurePath))
	if err != nil {
		return nil, fmt.Errorf("reading stack preimage for managed branch rename: %w", err)
	}
	ledger, err := os.ReadFile(internal.ManagedTemplateStatePath(featurePath))
	if err != nil {
		return nil, fmt.Errorf("reading ownership preimage for managed branch rename: %w", err)
	}
	state, err := internal.LoadManagedTemplateState(featurePath)
	if err != nil {
		return nil, err
	}
	return &managedRenameRecoveryContext{
		featurePath: featurePath,
		feature:     feature,
		evidence: internal.ManagedTemplateBranchRenameRecoveryEvidence{
			TargetRepo: targetRepo,
			OldName:    oldName, NewName: newName,
			OldGitBranch: oldGitBranch, NewGitBranch: newGitBranch,
			OldPath: oldPath, NewPath: newPath, ExpectedOID: expectedOID,
			StackPreimage: stackPreimage, OriginalLedger: ledger,
			Owner: state.Owner,
		},
	}, nil
}

func managedRenamePartialOutcome(
	context *managedRenameRecoveryContext,
	stage string,
	completed, pending []string,
	cause error,
) error {
	if context == nil {
		return fmt.Errorf("managed branch rename partial outcome during %s: %w", stage, cause)
	}
	evidenceRecord := context.evidence
	evidenceRecord.Stage = stage
	evidenceRecord.CompletedStages = append([]string(nil), completed...)
	evidenceRecord.PendingStages = append([]string(nil), pending...)
	evidence, evidenceErr := internal.RecordManagedTemplateBranchRenameRecoveryEvidence(
		context.featurePath, context.feature, evidenceRecord,
	)
	if evidenceErr != nil {
		return errors.Join(
			fmt.Errorf("managed branch rename partial outcome during %s: %w", stage, cause),
			fmt.Errorf("recording managed recovery evidence failed: %w", evidenceErr),
		)
	}
	return fmt.Errorf("managed branch rename partial outcome during %s; recovery evidence retained at %s: %w",
		stage, evidence, cause)
}

func rollbackManagedMaterializedBranchRename(
	retirement *preparedManagedWorktreeRetirement,
	context *managedRenameRecoveryContext,
	targetRepo, oldPath, newPath, oldGitBranch, newGitBranch, expectedOID string,
) error {
	if err := runRenameBranchExternalStep("before-rollback-rename", func() error { return nil }); err != nil {
		return managedRenamePartialOutcome(context, "rollback-ref-precheck",
			[]string{"old-worktree-removed"}, []string{"rollback-ref", "rollback-worktree", "rollback-managed-context"}, err)
	}
	if _, err := os.Lstat(oldPath); err == nil {
		return managedRenamePartialOutcome(context, "rollback-path-conflict",
			[]string{"old-worktree-removed"}, []string{"rollback-worktree", "rollback-managed-context"},
			fmt.Errorf("original worktree path was recreated concurrently: %s", oldPath))
	} else if !errors.Is(err, os.ErrNotExist) {
		return managedRenamePartialOutcome(context, "rollback-path-check",
			[]string{"old-worktree-removed"}, []string{"rollback-worktree", "rollback-managed-context"}, err)
	}
	if _, err := os.Lstat(newPath); err == nil {
		return managedRenamePartialOutcome(context, "rollback-destination-conflict",
			[]string{"old-worktree-removed"}, []string{"rollback-ref", "rollback-worktree", "rollback-managed-context"},
			fmt.Errorf("destination worktree path exists after failed creation: %s", newPath))
	} else if !errors.Is(err, os.ErrNotExist) {
		return managedRenamePartialOutcome(context, "rollback-destination-check",
			[]string{"old-worktree-removed"}, []string{"rollback-ref", "rollback-worktree", "rollback-managed-context"}, err)
	}

	oldOID, oldExists, err := localGitBranchOID(targetRepo, oldGitBranch)
	if err != nil {
		return managedRenamePartialOutcome(context, "rollback-old-ref-check",
			[]string{"old-worktree-removed"}, []string{"rollback-ref", "rollback-worktree", "rollback-managed-context"}, err)
	}
	newOID, newExists, err := localGitBranchOID(targetRepo, newGitBranch)
	if err != nil {
		return managedRenamePartialOutcome(context, "rollback-new-ref-check",
			[]string{"old-worktree-removed"}, []string{"rollback-ref", "rollback-worktree", "rollback-managed-context"}, err)
	}
	switch {
	case oldExists && oldOID == expectedOID:
		// The branch rename did not take effect. A foreign destination ref is
		// left untouched; restoring the original worktree remains safe.
	case !oldExists && newExists && newOID == expectedOID:
		if err := internal.RunDir(
			targetRepo, "git", "branch", "-m", newGitBranch, oldGitBranch,
		); err != nil {
			return managedRenamePartialOutcome(context, "rollback-branch-rename",
				[]string{"old-worktree-removed", "new-branch-created"},
				[]string{"rollback-ref", "rollback-worktree", "rollback-managed-context"}, err)
		}
	default:
		return managedRenamePartialOutcome(context, "rollback-ref-drift",
			[]string{"old-worktree-removed"}, []string{"rollback-ref", "rollback-worktree", "rollback-managed-context"},
			fmt.Errorf("expected commit %s; old=%q present=%v new=%q present=%v",
				expectedOID, oldOID, oldExists, newOID, newExists))
	}
	oldOID, oldExists, err = localGitBranchOID(targetRepo, oldGitBranch)
	if err != nil || !oldExists || oldOID != expectedOID {
		if err == nil {
			err = fmt.Errorf("restored branch is %q present=%v, expected %s", oldOID, oldExists, expectedOID)
		}
		return managedRenamePartialOutcome(context, "rollback-restored-ref-check",
			[]string{"old-worktree-removed", "original-ref-restored"},
			[]string{"rollback-worktree", "rollback-managed-context"}, err)
	}
	if err := runRenameBranchExternalStep("before-rollback-worktree-add", func() error {
		return internal.RunDir(targetRepo, "git", "worktree", "add", oldPath, oldGitBranch)
	}); err != nil {
		return managedRenamePartialOutcome(context, "rollback-worktree-add",
			[]string{"old-worktree-removed", "original-ref-restored"},
			[]string{"rollback-worktree", "rollback-managed-context"}, err)
	}
	if err := verifyManagedRenameRollbackWorktree(
		targetRepo, oldPath, oldGitBranch, expectedOID,
	); err != nil {
		return managedRenamePartialOutcome(context, "rollback-worktree-identity",
			[]string{"old-worktree-removed", "original-ref-restored", "original-worktree-restored"},
			[]string{"rollback-managed-context"}, err)
	}
	if err := retirement.restoreAfterRollback(); err != nil {
		return managedRenamePartialOutcome(context, "rollback-managed-context",
			[]string{"old-worktree-removed", "original-ref-restored", "original-worktree-restored"},
			[]string{"rollback-managed-context"}, err)
	}
	return nil
}

func wrapRenameRollbackError(action string, err error) error {
	if err == nil {
		return nil
	}
	return fmt.Errorf("%s failed: %w", action, err)
}

