func (tx *managedRecoveryRoot) publish(staged managedStagedObject, destination string) error {
	parent := filepath.Dir(destination)
	intent := managedPendingIntent{
		Effect: "publish-active", OriginalPath: destination,
		PrivatePath: staged.path, Kind: staged.kind,
	}
	if staged.kind == "file" {
		expected := staged.file
		intent.ExpectedFile = &expected
	} else {
		expected := staged.link
		intent.ExpectedLink = &expected
	}
	if err := tx.recordIntent(intent); err != nil {
		return err
	}
	sourceParentPath := filepath.Dir(staged.path)
	sourceParent, _, err := managedOpenPinnedDirectory(tx.root, sourceParentPath, false)
	if err != nil {
		return fmt.Errorf("opening pinned staging parent %s: %w", sourceParentPath, err)
	}
	defer sourceParent.Close() //nolint:errcheck
	destinationParent, destinationIdentity, err := managedOpenPinnedDirectory(tx.root, parent, true)
	if err != nil {
		return fmt.Errorf("opening pinned destination parent %s: %w", parent, err)
	}
	defer destinationParent.Close() //nolint:errcheck
	if err := managedLinkPinned(
		sourceParent, filepath.Base(staged.path),
		destinationParent, filepath.Base(destination),
	); err != nil {
		return fmt.Errorf("publishing managed path without replacement %s: %w",
			filepath.Join(tx.displayPath, destination), err)
	}
	if err := destinationParent.Sync(); err != nil {
		return err
	}
	if err := managedVerifyPinnedDirectoryBinding(tx.root, parent, destinationIdentity); err != nil {
		return fmt.Errorf("managed destination parent binding changed at %s: %w",
			filepath.Join(tx.displayPath, parent), err)
	}
	return nil
}

func (tx *managedRecoveryRoot) preserveFile(destination string, expected managedFileObservation) error {
	recovery, err := tx.uniquePath("old-file")
	if err != nil {
		return err
	}
	if err := tx.recordIntent(managedPendingIntent{
		Effect: "preserve-active", OriginalPath: destination,
		PrivatePath: recovery, Kind: "file", ExpectedFile: &expected,
	}); err != nil {
		return err
	}
	if err := managedRenameNoReplace(tx.root, destination, recovery); err != nil {
		return err
	}
	if err := tx.syncRenameParents(destination, recovery); err != nil {
		return err
	}
	got, err := observeManagedFileRoot(tx.root, recovery)
	if err != nil {
		return fmt.Errorf("inspecting captured file failed; preserved at %s with pending evidence %s: %w",
			filepath.Join(tx.displayPath, recovery), filepath.Join(tx.displayPath, tx.journal), err)
	}
	if got != expected {
		return tx.restoreAfterPreservationFailure(
			destination, recovery, "file", &got, nil,
			errors.New("captured file does not match planned identity/content"),
		)
	}
	tx.preserved = append(tx.preserved, managedPreservedObject{
		active: destination, recovery: recovery, kind: "file", file: expected,
	})
	return nil
}

func (tx *managedRecoveryRoot) preserveLink(destination string, expected managedLinkObservation) error {
	recovery, err := tx.uniquePath("old-link")
	if err != nil {
		return err
	}
	if err := tx.recordIntent(managedPendingIntent{
		Effect: "preserve-active", OriginalPath: destination,
		PrivatePath: recovery, Kind: "link", ExpectedLink: &expected,
	}); err != nil {
		return err
	}
	if err := managedRenameNoReplace(tx.root, destination, recovery); err != nil {
		return err
	}
	if err := tx.syncRenameParents(destination, recovery); err != nil {
		return err
	}
	got, err := observeManagedLinkRoot(tx.root, recovery)
	if err != nil {
		return fmt.Errorf("inspecting captured symbolic link failed; preserved at %s with pending evidence %s: %w",
			filepath.Join(tx.displayPath, recovery), filepath.Join(tx.displayPath, tx.journal), err)
	}
	if got != expected {
		return tx.restoreAfterPreservationFailure(
			destination, recovery, "link", nil, &got,
			errors.New("captured symbolic link does not match planned identity/target"),
		)
	}
	tx.preserved = append(tx.preserved, managedPreservedObject{
		active: destination, recovery: recovery, kind: "link", link: expected,
	})
	return nil
}

func (tx *managedRecoveryRoot) syncRenameParents(original, private string) error {
	var errs []error
	for _, parent := range []string{filepath.Dir(original), filepath.Dir(private)} {
		if err := managedSyncRootDir(tx.root, parent); err != nil {
			errs = append(errs, err)
		}
	}
	return errors.Join(errs...)
}

func (tx *managedRecoveryRoot) restoreAfterPreservationFailure(
	destination, recovery, kind string,
	file *managedFileObservation,
	link *managedLinkObservation,
	cause error,
) error {
	if err := tx.recordIntent(managedPendingIntent{
		Effect: "restore-active", OriginalPath: destination,
		PrivatePath: recovery, Kind: kind,
		ExpectedFile: file, ExpectedLink: link,
	}); err != nil {
		return fmt.Errorf("%w; restore intent could not be persisted, object remains at %s: %v",
			cause, filepath.Join(tx.displayPath, recovery), err)
	}
	restoreErr := managedRenameNoReplace(tx.root, recovery, destination)
	if restoreErr == nil {
		restoreErr = tx.syncRenameParents(recovery, destination)
	}
	if restoreErr != nil {
		return fmt.Errorf("%w; preserved conflicting objects at %s and %s: %v",
			cause, filepath.Join(tx.displayPath, destination),
			filepath.Join(tx.displayPath, recovery), restoreErr)
	}
	return fmt.Errorf("%w; restored captured object at %s; pending evidence retained at %s",
		cause, filepath.Join(tx.displayPath, destination),
		filepath.Join(tx.displayPath, tx.journal))
}

func (tx *managedRecoveryRoot) preflightCleanup() error {
	for _, preserved := range tx.preserved {
		if ManagedTemplateApplyStepHook != nil {
			if err := ManagedTemplateApplyStepHook(
				"before-cleanup", filepath.Join(tx.displayPath, preserved.recovery),
			); err != nil {
				return fmt.Errorf("cleanup stopped with recovery object preserved at %s: %w",
					filepath.Join(tx.displayPath, preserved.recovery), err)
			}
		}
	}
	for _, preserved := range tx.preserved {
		if preserved.kind == "file" {
			got, err := observeManagedFileRoot(tx.root, preserved.recovery)
			if err != nil {
				return fmt.Errorf("verifying recovery copy %s: %w",
					filepath.Join(tx.displayPath, preserved.recovery), err)
			}
			if got != preserved.file {
				return fmt.Errorf("recovery copy changed; preserved at %s with pending evidence %s",
					filepath.Join(tx.displayPath, preserved.recovery),
					filepath.Join(tx.displayPath, tx.journal))
			}
		} else {
			got, err := observeManagedLinkRoot(tx.root, preserved.recovery)
			if err != nil {
				return fmt.Errorf("verifying recovery link %s: %w",
					filepath.Join(tx.displayPath, preserved.recovery), err)
			}
			if got != preserved.link {
				return fmt.Errorf("recovery link changed; preserved at %s with pending evidence %s",
					filepath.Join(tx.displayPath, preserved.recovery),
					filepath.Join(tx.displayPath, tx.journal))
			}
		}
	}
	stagedByOriginal := make(map[string]managedStagedObject, len(tx.staged))
	for _, staged := range tx.staged {
		stagedByOriginal[staged.original] = staged
		var (
			stagedMatches bool
			activeMatches bool
			err           error
		)
		if staged.kind == "file" {
			var got managedFileObservation
			got, err = observeManagedFileRoot(tx.root, staged.path)
			stagedMatches = got == staged.file
			if err == nil {
				got, err = observeManagedFileRoot(tx.root, staged.original)
				activeMatches = got == staged.file
			}
		} else {
			var got managedLinkObservation
			got, err = observeManagedLinkRoot(tx.root, staged.path)
			stagedMatches = got == staged.link
			if err == nil {
				got, err = observeManagedLinkRoot(tx.root, staged.original)
				activeMatches = got == staged.link
			}
		}
		if err != nil {
			return fmt.Errorf("verifying staged and active managed object %s: %w",
				filepath.Join(tx.displayPath, staged.original), err)
		}
		if !stagedMatches {
			return fmt.Errorf("staging %s changed; preserved at %s with pending evidence %s",
				staged.kind, filepath.Join(tx.displayPath, staged.path),
				filepath.Join(tx.displayPath, tx.journal))
		}
		if !activeMatches {
			return fmt.Errorf("active managed %s no longer matches staged publication at %s; pending evidence retained at %s",
				staged.kind, filepath.Join(tx.displayPath, staged.original),
				filepath.Join(tx.displayPath, tx.journal))
		}
	}
	for _, preserved := range tx.preserved {
		if _, replaced := stagedByOriginal[preserved.active]; replaced {
			continue
		}
		if _, err := tx.root.Lstat(preserved.active); !errors.Is(err, fs.ErrNotExist) {
			if err != nil {
				return fmt.Errorf("verifying removed managed path %s: %w",
					filepath.Join(tx.displayPath, preserved.active), err)
			}
			return fmt.Errorf("removed managed path was recreated at %s; pending evidence retained at %s",
				filepath.Join(tx.displayPath, preserved.active),
				filepath.Join(tx.displayPath, tx.journal))
		}
	}
	if err := tx.verifyCleanupContents(true); err != nil {
		return err
	}
	return nil
}

func (tx *managedRecoveryRoot) cleanupVerified() error {
	for _, preserved := range tx.preserved {
		intent := managedPendingIntent{
			Effect: "cleanup-private", OriginalPath: preserved.active,
			PrivatePath: preserved.recovery, Kind: preserved.kind,
		}
		if preserved.kind == "file" {
			expected := preserved.file
			intent.ExpectedFile = &expected
		} else {
			expected := preserved.link
			intent.ExpectedLink = &expected
		}
		if err := tx.recordIntent(intent); err != nil {
			return err
		}
		if err := tx.removeVerifiedPrivate(
			preserved.recovery, preserved.kind, preserved.file, preserved.link,
		); err != nil {
			return fmt.Errorf("cleaning verified recovery object %s: %w",
				filepath.Join(tx.displayPath, preserved.recovery), err)
		}
	}
	for _, staged := range tx.staged {
		intent := managedPendingIntent{
			Effect: "cleanup-private", OriginalPath: staged.original,
			PrivatePath: staged.path, Kind: staged.kind,
		}
		if staged.kind == "file" {
			expected := staged.file
			intent.ExpectedFile = &expected
		} else {
			expected := staged.link
			intent.ExpectedLink = &expected
		}
		if err := tx.recordIntent(intent); err != nil {
			return err
		}
		if err := tx.removeVerifiedPrivate(
			staged.path, staged.kind, staged.file, staged.link,
		); err != nil {
			return err
		}
	}
	if err := tx.verifyCleanupContents(false); err != nil {
		return err
	}
	for _, metadata := range tx.intentFiles {
		if err := tx.removeVerifiedMetadata(metadata); err != nil {
			return err
		}
	}
	entries, err := fs.ReadDir(tx.root.FS(), tx.opDir)
	if err != nil {
		return err
	}
	if len(entries) != 1 || entries[0].Name() != filepath.Base(tx.journal) {
		unexpected := tx.opDir
		if len(entries) > 0 {
			unexpected = filepath.Join(tx.opDir, entries[0].Name())
		}
		return fmt.Errorf("unexpected recovery content %s prevents cleanup",
			filepath.Join(tx.displayPath, unexpected))
	}
	if err := tx.removeVerifiedMetadata(tx.journalFile); err != nil {
		return err
	}
	entries, err = fs.ReadDir(tx.root.FS(), tx.opDir)
	if err != nil {
		return err
	}
	if len(entries) != 0 {
		return fmt.Errorf("unexpected recovery content %s prevents cleanup",
			filepath.Join(tx.displayPath, tx.opDir, entries[0].Name()))
	}
	if err := managedSyncRootDir(tx.root, tx.opDir); err != nil {
		return err
	}
	if err := tx.root.Remove(tx.opDir); err != nil {
		return err
	}
	if err := managedSyncRootDir(tx.root, managedTemplateRecoveryName); err != nil {
		return err
	}
	if err := tx.root.Remove(managedTemplateRecoveryName); err != nil && !errors.Is(err, fs.ErrNotExist) {
		return err
	}
	if err := managedSyncRootDir(tx.root, "."); err != nil {
		return err
	}
	tx.cleaned = true
	return nil
}

func (tx *managedRecoveryRoot) removeVerifiedPrivate(
	path, kind string,
	expectedFile managedFileObservation,
	expectedLink managedLinkObservation,
) error {
	if kind == "file" {
		got, err := observeManagedFileRoot(tx.root, path)
		if err != nil {
			return err
		}
		if got != expectedFile {
			return fmt.Errorf("private file identity/content changed at %s",
				filepath.Join(tx.displayPath, path))
		}
	} else {
		got, err := observeManagedLinkRoot(tx.root, path)
		if err != nil {
			return err
		}
		if got != expectedLink {
			return fmt.Errorf("private link identity/target changed at %s",
				filepath.Join(tx.displayPath, path))
		}
	}
	return tx.root.Remove(path)
}

func (tx *managedRecoveryRoot) removeVerifiedMetadata(metadata managedPrivateMetadata) error {
	got, err := observeManagedFileRoot(tx.root, metadata.path)
	if err != nil {
		return err
	}
	if got != metadata.file {
		return fmt.Errorf("private recovery metadata changed at %s",
			filepath.Join(tx.displayPath, metadata.path))
	}
	return tx.root.Remove(metadata.path)
}

func (tx *managedRecoveryRoot) verifyCleanupContents(includeObjects bool) error {
	entries, err := fs.ReadDir(tx.root.FS(), tx.opDir)
	if err != nil {
		return err
	}
	allowed := map[string]bool{filepath.Base(tx.journal): true}
	for _, metadata := range tx.intentFiles {
		allowed[filepath.Base(metadata.path)] = true
	}
	if includeObjects {
		for _, preserved := range tx.preserved {
			allowed[filepath.Base(preserved.recovery)] = true
		}
		for _, staged := range tx.staged {
			allowed[filepath.Base(staged.path)] = true
		}
	}
	for _, entry := range entries {
		if !allowed[entry.Name()] {
			return fmt.Errorf("unexpected recovery content %s prevents cleanup",
				filepath.Join(tx.displayPath, tx.opDir, entry.Name()))
		}
	}
	return nil
}

func observeManagedFileRoot(root *os.Root, relative string) (managedFileObservation, error) {
	info, err := root.Lstat(relative)
	if errors.Is(err, fs.ErrNotExist) {
		return managedFileObservation{}, nil
	}
	if err != nil {
		return managedFileObservation{}, err
	}
	identity, err := managedIdentityFromInfo(info)
	if err != nil {
		return managedFileObservation{}, err
	}
	kind := managedFileKind(info.Mode())
	if kind != "file" {
		return managedFileObservation{
			Exists: true, Kind: kind, Device: identity.Device, Inode: identity.Inode,
		}, nil
	}
	file, err := root.Open(relative)
	if err != nil {
		return managedFileObservation{}, err
	}
	defer file.Close() //nolint:errcheck
	before, err := file.Stat()
	if err != nil {
		return managedFileObservation{}, err
	}
	beforeIdentity, err := managedIdentityFromInfo(before)
	if err != nil {
		return managedFileObservation{}, err
	}
	data, err := io.ReadAll(file)
	if err != nil {
		return managedFileObservation{}, err
	}
	after, err := file.Stat()
	if err != nil {
		return managedFileObservation{}, err
	}
	afterIdentity, err := managedIdentityFromInfo(after)
	if err != nil {
		return managedFileObservation{}, err
	}
	if beforeIdentity != identity || afterIdentity != identity ||
		before.Mode().Perm() != after.Mode().Perm() ||
		before.Size() != after.Size() || !before.ModTime().Equal(after.ModTime()) {
		return managedFileObservation{}, errors.New("regular file changed while hashing")
	}
	return managedFileObservation{
		Exists: true, Kind: "file", Hash: digestBytes(data),
		Mode: uint32(before.Mode().Perm()), Device: identity.Device, Inode: identity.Inode,
	}, nil
}

func observeManagedLinkRoot(root *os.Root, relative string) (managedLinkObservation, error) {
	info, err := root.Lstat(relative)
	if errors.Is(err, fs.ErrNotExist) {
		return managedLinkObservation{}, nil
	}
	if err != nil {
		return managedLinkObservation{}, err
	}
	identity, err := managedIdentityFromInfo(info)
	if err != nil {
		return managedLinkObservation{}, err
	}
	observation := managedLinkObservation{
		Exists: true, Kind: managedFileKind(info.Mode()),
		Device: identity.Device, Inode: identity.Inode,
	}
	if observation.Kind == "symlink" {
		target, err := root.Readlink(relative)
		if err != nil {
			return managedLinkObservation{}, err
		}
		observation.Target = target
	}
	return observation, nil
}

func applyManagedTemplatePlanPreserved(plan *ManagedTemplatePlan) (retErr error) {
	featureRoot, err := openManagedFeatureRoot(plan)
	if err != nil {
		return err
	}
	defer func() { retErr = errors.Join(retErr, featureRoot.Close()) }()

	opID, err := managedOperationID()
	if err != nil {
		return err
	}
	featurePaths := make([]string, 0, len(plan.Removals)+len(plan.Writes)+1)
	worktreePaths := make(map[string][]string)
	for _, removal := range plan.Removals {
		if removal.Kind == "link" {
			worktreePaths[removal.root] = append(worktreePaths[removal.root], removal.relative)
		} else {
			featurePaths = append(featurePaths, managedFeatureRelative(removal.Role, removal.relative))
		}
	}
	for _, write := range plan.Writes {
		featurePaths = append(featurePaths, managedFeatureRelative(write.Role, write.Relative))
	}
	for _, link := range plan.LinkWrites {
		worktreePaths[link.WorktreeRoot] = append(worktreePaths[link.WorktreeRoot], link.Relative)
	}
	if plan.StateChanged {
		featurePaths = append(featurePaths, managedTemplateStateName)
	}

	var featureTx *managedRecoveryRoot
	if len(featurePaths) > 0 {
		featureTx, err = newManagedRecoveryRoot(
			featureRoot, plan.Request.FeaturePath, opID, plan.Request.Feature, featurePaths,
		)
		if err != nil {
			return err
		}
	}
	worktreeTx := make(map[string]*managedRecoveryRoot)
	for path, paths := range worktreePaths {
		var expected managedWorktreeIdentity
		for _, target := range plan.worktreeChecks {
			if filepath.Clean(target.Path) == filepath.Clean(path) {
				expected = plan.worktreeIdentities[target.Name]
				break
			}
		}
		root, openErr := openManagedWorktreeRoot(path, expected)
		if openErr != nil {
			return managedPendingApplyError(openErr, featureTx, worktreeTx)
		}
		tx, txErr := newManagedRecoveryRoot(root, path, opID, plan.Request.Feature, paths)
		if txErr != nil {
			_ = root.Close()
			return managedPendingApplyError(txErr, featureTx, worktreeTx)
		}
		worktreeTx[path] = tx
	}
	defer func() {
		for _, tx := range worktreeTx {
			retErr = errors.Join(retErr, tx.root.Close())
		}
	}()

	stagedWrites := make([]managedStagedObject, len(plan.Writes))
	for i, write := range plan.Writes {
		relative := managedFeatureRelative(write.Role, write.Relative)
		staged, stageErr := featureTx.stageRegular(relative, write.Data, write.Mode)
		if stageErr != nil {
			return managedPendingApplyError(stageErr, featureTx, worktreeTx)
		}
		stagedWrites[i] = staged
	}
	stagedLinks := make([]managedStagedObject, len(plan.LinkWrites))
	for i, link := range plan.LinkWrites {
		tx := worktreeTx[link.WorktreeRoot]
		staged, stageErr := tx.stageLink(link.Relative, link.Target)
		if stageErr != nil {
			return managedPendingApplyError(stageErr, featureTx, worktreeTx)
		}
		stagedLinks[i] = staged
		if err := setManagedPlannedLinkIdentity(
			&plan.NewState, link.Worktree, link.Relative, staged.link,
			plan.worktreeIdentities[link.Worktree],
		); err != nil {
			return managedPendingApplyError(err, featureTx, worktreeTx)
		}
	}
	if err := validateManagedTemplateState(plan.NewState, false); err != nil {
		return managedPendingApplyError(
			fmt.Errorf("generated managed template state is invalid before publication: %w", err),
			featureTx, worktreeTx,
		)
	}
	var stagedState managedStagedObject
	if plan.StateChanged {
		stateData, marshalErr := marshalManagedTemplateState(plan.NewState)
		if marshalErr != nil {
			return managedPendingApplyError(marshalErr, featureTx, worktreeTx)
		}
		stagedState, err = featureTx.stageRegular(managedTemplateStateName, stateData, 0o600)
		if err != nil {
			return managedPendingApplyError(err, featureTx, worktreeTx)
		}
	}

	totalEffects := len(plan.Removals) + len(plan.Writes) + len(plan.LinkWrites)
	if plan.StateChanged {
		totalEffects++
	}
	completed := 0
	for _, removal := range plan.Removals {
		if ManagedTemplateApplyStepHook != nil {
			if err := ManagedTemplateApplyStepHook("before-remove", removal.Path); err != nil {
				return managedPendingApplyError(managedTemplateProgressError(completed, totalEffects,
					fmt.Errorf("stopped before removing %s: %w", removal.Path, err)), featureTx, worktreeTx)
			}
		}
		if removal.Kind == "link" {
			tx := worktreeTx[removal.root]
			tracked, err := managedGitTracked(removal.root, removal.relative)
			if err != nil {
				return managedPendingApplyError(managedTemplateProgressError(completed, totalEffects,
					fmt.Errorf("rechecking Git tracking before removing %s: %w", removal.Path, err)),
					featureTx, worktreeTx)
			}
			if tracked {
				return managedPendingApplyError(managedTemplateProgressError(completed, totalEffects,
					fmt.Errorf("worktree destination %s became tracked by Git", removal.Path)),
					featureTx, worktreeTx)
			}
			if err := tx.preserveLink(removal.relative, removal.linkBefore); err != nil {
				return managedPendingApplyError(managedTemplateProgressError(completed, totalEffects,
					fmt.Errorf("preserving removal %s failed: %w", removal.Path, err)), featureTx, worktreeTx)
			}
		} else {
			relative := managedFeatureRelative(removal.Role, removal.relative)
			if err := featureTx.preserveFile(relative, removal.fileBefore); err != nil {
				return managedPendingApplyError(managedTemplateProgressError(completed, totalEffects,
					fmt.Errorf("preserving removal %s failed: %w", removal.Path, err)), featureTx, worktreeTx)
			}
		}
		completed++
	}
	for i, write := range plan.Writes {
		path := filepath.Join(write.Root, filepath.FromSlash(write.Relative))
		if ManagedTemplateApplyStepHook != nil {
			if err := ManagedTemplateApplyStepHook("before-write", path); err != nil {
				return managedPendingApplyError(managedTemplateProgressError(completed, totalEffects,
					fmt.Errorf("stopped before writing %s: %w", path, err)), featureTx, worktreeTx)
			}
		}
		relative := managedFeatureRelative(write.Role, write.Relative)
		if write.Before.Exists {
			if err := featureTx.preserveFile(relative, write.Before); err != nil {
				return managedPendingApplyError(managedTemplateProgressError(completed, totalEffects,
					fmt.Errorf("preserving replacement %s failed: %w", path, err)), featureTx, worktreeTx)
			}
		}
		if err := featureTx.publish(stagedWrites[i], relative); err != nil {
			return managedPendingApplyError(managedTemplateProgressError(completed, totalEffects,
				fmt.Errorf("write %s failed: %w", path, err)), featureTx, worktreeTx)
		}
		completed++
	}
	for i, link := range plan.LinkWrites {
		path := filepath.Join(link.WorktreeRoot, filepath.FromSlash(link.Relative))
		if ManagedTemplateApplyStepHook != nil {
			if err := ManagedTemplateApplyStepHook("before-link", path); err != nil {
				return managedPendingApplyError(managedTemplateProgressError(completed, totalEffects,
					fmt.Errorf("stopped before linking %s: %w", path, err)), featureTx, worktreeTx)
			}
		}
		if err := validateManagedOwnedSourceFiles(
			plan.Request.FeaturePath, plan.ownedSourceChecks,
		); err != nil {
			return managedPendingApplyError(managedTemplateProgressError(completed, totalEffects,
				fmt.Errorf("managed source changed before linking %s: %w", path, err)),
				featureTx, worktreeTx)
		}
		tracked, err := managedGitTracked(link.WorktreeRoot, link.Relative)
		if err != nil {
			return managedPendingApplyError(managedTemplateProgressError(completed, totalEffects,
				fmt.Errorf("rechecking Git tracking before linking %s: %w", path, err)),
				featureTx, worktreeTx)
		}
		if tracked {
			return managedPendingApplyError(managedTemplateProgressError(completed, totalEffects,
				fmt.Errorf("worktree destination %s became tracked by Git", path)),
				featureTx, worktreeTx)
		}
		if err := worktreeTx[link.WorktreeRoot].publish(stagedLinks[i], link.Relative); err != nil {
			return managedPendingApplyError(managedTemplateProgressError(completed, totalEffects,
				fmt.Errorf("link %s failed: %w", path, err)), featureTx, worktreeTx)
		}
		completed++
	}
	if plan.StateChanged {
		if ManagedTemplateApplyStepHook != nil {
			if err := ManagedTemplateApplyStepHook("before-state", ManagedTemplateStatePath(plan.Request.FeaturePath)); err != nil {
				return managedPendingApplyError(managedTemplateProgressError(completed, totalEffects,
					fmt.Errorf("filesystem effects completed but ownership state publication stopped: %w", err)),
					featureTx, worktreeTx)
			}
		}
		if err := revalidateManagedOwnedLinks(plan); err != nil {
			return managedPendingApplyError(managedTemplateProgressError(completed, totalEffects,
				fmt.Errorf("managed link ownership changed before ledger publication: %w", err)),
				featureTx, worktreeTx)
		}
		if err := validateManagedOwnedSourceFiles(
			plan.Request.FeaturePath, plan.ownedSourceChecks,
		); err != nil {
			return managedPendingApplyError(managedTemplateProgressError(completed, totalEffects,
				fmt.Errorf("managed source changed before ledger publication: %w", err)),
				featureTx, worktreeTx)
		}
		if err := revalidateManagedRetiredLinks(plan); err != nil {
			return managedPendingApplyError(managedTemplateProgressError(completed, totalEffects,
				fmt.Errorf("retired managed link ownership changed before ledger publication: %w", err)),
				featureTx, worktreeTx)
		}
		if plan.StateBefore.Exists {
			if err := featureTx.preserveFile(managedTemplateStateName, plan.StateBefore); err != nil {
				return managedPendingApplyError(managedTemplateProgressError(completed, totalEffects,
					fmt.Errorf("preserving ownership state failed: %w", err)), featureTx, worktreeTx)
			}

			if ManagedTemplateApplyStepHook != nil {
				if err := ManagedTemplateApplyStepHook(
					"after-state-preserve", ManagedTemplateStatePath(plan.Request.FeaturePath),
				); err != nil {
					return managedPendingApplyError(managedTemplateProgressError(completed, totalEffects,
						fmt.Errorf("ownership state was preserved but replacement publication stopped: %w", err)),
						featureTx, worktreeTx)
				}
			}
		}
		if err := featureTx.publish(stagedState, managedTemplateStateName); err != nil {
			return managedPendingApplyError(managedTemplateProgressError(completed, totalEffects,
				fmt.Errorf("publishing managed template ownership state: %w", err)), featureTx, worktreeTx)
		}
	}

	worktreeRoots := make([]string, 0, len(worktreeTx))
	for root := range worktreeTx {
		worktreeRoots = append(worktreeRoots, root)
	}
	sort.Strings(worktreeRoots)
	cleanupTxs := make([]*managedRecoveryRoot, 0, len(worktreeRoots)+1)
	for _, root := range worktreeRoots {
		cleanupTxs = append(cleanupTxs, worktreeTx[root])
	}
	if featureTx != nil {
		cleanupTxs = append(cleanupTxs, featureTx)
	}
	for _, tx := range cleanupTxs {
		if err := tx.preflightCleanup(); err != nil {
			return managedPendingApplyError(fmt.Errorf("managed template update succeeded but cleanup failed: %w", err),
				featureTx, worktreeTx)
		}
	}
	for _, tx := range cleanupTxs {
		if err := tx.cleanupVerified(); err != nil {
			return managedPendingApplyError(fmt.Errorf("managed template update succeeded but cleanup failed: %w", err),
				featureTx, worktreeTx)
		}
	}
	return nil
}

func revalidateManagedOwnedLinks(plan *ManagedTemplatePlan) error {
	role, ok := plan.NewState.Roles[string(ManagedTemplateRoleWorktree)]
	if !ok || len(role.Links) == 0 {
		return nil
	}
	targets := make(map[string]injectWorktreeTarget, len(plan.worktreeChecks))
	for _, target := range plan.worktreeChecks {
		targets[target.Name] = target
	}
	for _, link := range role.Links {
		target, ok := targets[link.Worktree]
		if !ok {
			return fmt.Errorf("recorded worktree %q is no longer in the pinned plan", link.Worktree)
		}
		tracked, err := managedGitTracked(target.Path, link.Path)
		if err != nil {
			return err
		}
		if tracked {
			return fmt.Errorf("worktree %q destination %s is tracked by Git",
				link.Worktree, filepath.Join(target.Path, filepath.FromSlash(link.Path)))
		}
		observation, err := observeManagedLink(target.Path, link.Path)
		if err != nil {
			return err
		}
		destination := filepath.Join(target.Path, filepath.FromSlash(link.Path))
		expectedTarget, err := filepath.Rel(
			filepath.Dir(destination),
			filepath.Join(InjectPath(plan.Request.FeaturePath), filepath.FromSlash(link.Source)),
		)
		if err != nil {
			return err
		}
		if err := matchOwnedLink(
			observation, link, plan.worktreeIdentities[link.Worktree],
			link.Source, expectedTarget,
		); err != nil {
			return fmt.Errorf("worktree %q destination %s: %w", link.Worktree, destination, err)
		}
	}
	return nil
}

func revalidateManagedRetiredLinks(plan *ManagedTemplatePlan) error {
	for _, retired := range plan.retiredLinks {
		tracked, err := managedGitTracked(retired.worktreeRoot, retired.owned.Path)
		if err != nil {
			return err
		}
		if tracked {
			return fmt.Errorf("worktree %q destination %s is tracked by Git",
				retired.owned.Worktree,
				filepath.Join(retired.worktreeRoot, filepath.FromSlash(retired.owned.Path)))
		}
		observation, err := observeManagedLink(retired.worktreeRoot, retired.owned.Path)
		if err != nil {
			return err
		}
		if observation != retired.before {
			return fmt.Errorf("worktree %q destination %s changed after retirement planning",
				retired.owned.Worktree,
				filepath.Join(retired.worktreeRoot, filepath.FromSlash(retired.owned.Path)))
		}
		if err := matchOwnedLink(
			observation,
			retired.owned,
			plan.worktreeIdentities[retired.owned.Worktree],
			retired.owned.Source,
			retired.owned.Target,
		); err != nil {
			return fmt.Errorf("worktree %q destination %s: %w",
				retired.owned.Worktree,
				filepath.Join(retired.worktreeRoot, filepath.FromSlash(retired.owned.Path)),
				err)
		}
	}
	return nil
}

func managedFeatureRelative(role ManagedTemplateRole, relative string) string {
	if role == ManagedTemplateRoleWorktree {
		return filepath.Join(InjectDir, filepath.FromSlash(relative))
	}
	return filepath.FromSlash(relative)
}

func setManagedPlannedLinkIdentity(
	state *ManagedTemplateState,
	worktree, path string,
	observation managedLinkObservation,
	worktreeIdentity managedWorktreeIdentity,
) error {
	role := state.Roles[string(ManagedTemplateRoleWorktree)]
	for i := range role.Links {
		if role.Links[i].Worktree == worktree && role.Links[i].Path == path {
			role.Links[i].Device = observation.Device
			role.Links[i].Inode = observation.Inode
			role.Links[i].WorktreeDevice = worktreeIdentity.WorktreeDevice
			role.Links[i].WorktreeInode = worktreeIdentity.WorktreeInode
			role.Links[i].GitDirDevice = worktreeIdentity.GitDirDevice
			role.Links[i].GitDirInode = worktreeIdentity.GitDirInode
			state.Roles[string(ManagedTemplateRoleWorktree)] = role
			return nil
		}
	}
	return fmt.Errorf("planned managed link %s/%s is missing from generated ownership state", worktree, path)
}

func managedPendingApplyError(
	cause error,
	feature *managedRecoveryRoot,
	worktrees map[string]*managedRecoveryRoot,
) error {
	var paths []string
	if feature != nil && !feature.cleaned {
		paths = append(paths, feature.pendingEvidencePath())
	}
	for _, tx := range worktrees {
		if !tx.cleaned {
			paths = append(paths, tx.pendingEvidencePath())
		}
	}
	sort.Strings(paths)
	if len(paths) == 0 {
		return cause
	}
	return fmt.Errorf("%w; preserved pending evidence: %s", cause, joinManagedPaths(paths))
}

func (tx *managedRecoveryRoot) pendingEvidencePath() string {
	journal := filepath.Join(tx.displayPath, tx.journal)
	if _, err := os.Lstat(journal); err == nil {
		return journal
	}
	return filepath.Join(tx.displayPath, managedTemplateRecoveryName)
}

func joinManagedPaths(paths []string) string {
	result := ""
	for i, path := range paths {
		if i > 0 {
			result += ", "
		}
		result += path
	}
	return result
}

package internal

import (
	"bytes"
	"crypto/rand"
	"errors"
	"fmt"
	"io"
	"io/fs"
	"os"
	"path/filepath"
	"sort"
	"strings"
	"unicode"

	"gopkg.in/yaml.v3"
)

const (
	TemplateScopeGlobal = "global"
	TemplateScopeRepo   = "repo"
)

const (
	templateManifestVersion     = 1
	templateRegistryIdentityDir = ".registry-identity"
)

type TemplateReference struct {
	Scope string
	Name  string
}

type ResolvedTemplate struct {
	Reference TemplateReference
	Path      string
	OriginID  string
}

type NamedTemplateEntry struct {
	Name      string
	Scope     string
	Path      string
	Effective bool
}

type TemplateManifest struct {
	Version  int                     `yaml:"version"`
	Guidance map[string]string       `yaml:"guidance,omitempty"`
	Skills   []TemplateManifestSkill `yaml:"skills,omitempty"`
}

type TemplateManifestSkill struct {
	Name   string   `yaml:"name"`
	Roles  []string `yaml:"roles"`
	Agents []string `yaml:"agents,omitempty"`
}

type TemplatePackageFile struct {
	Path string
	Data []byte
	Mode fs.FileMode
}

type TemplatePackage struct {
	Root     string
	Feature  []TemplatePackageFile
	Inject   []TemplatePackageFile
	Metadata []TemplatePackageFile
	Manifest TemplateManifest

	rootIdentity managedObjectIdentity
}

var templateRegistryAfterLockHook func(root string) error
var templatePackageAfterOpenHook func(root string) error

func ValidateTemplateName(name string) error {
	if name == "" {
		return errors.New("template name cannot be empty")
	}
	if name == "." || name == ".." || strings.HasPrefix(name, ".") {
		return fmt.Errorf("template name %q is hidden or reserved", name)
	}
	if filepath.IsAbs(name) || filepath.VolumeName(name) != "" ||
		strings.ContainsAny(name, `/\:`) || filepath.Clean(name) != name {
		return fmt.Errorf("template name %q must be one path component without ':'", name)
	}
	for _, r := range name {
		if unicode.IsControl(r) {
			return fmt.Errorf("template name %q contains a control character", name)
		}
	}
	return nil
}

func ParseTemplateReference(value string) (TemplateReference, error) {
	if value == "" {
		return TemplateReference{}, errors.New("template reference cannot be empty")
	}
	ref := TemplateReference{Name: value}
	if before, after, ok := strings.Cut(value, ":"); ok {
		switch before {
		case TemplateScopeRepo, TemplateScopeGlobal:
			ref.Scope = before
		default:
			return TemplateReference{}, fmt.Errorf("template reference %q has unknown scope %q", value, before)
		}
		ref.Name = after
		if strings.Contains(after, ":") {
			return TemplateReference{}, fmt.Errorf("template reference %q contains multiple scope separators", value)
		}
	}
	if err := ValidateTemplateName(ref.Name); err != nil {
		return TemplateReference{}, err
	}
	return ref, nil
}

func ValidateTemplateReferenceSyntax(value string) error {
	_, err := ParseTemplateReference(value)
	return err
}

func GlobalTemplateRegistryRoot() (string, error) {
	home, err := os.UserHomeDir()
	if err != nil {
		return "", fmt.Errorf("resolving home directory: %w", err)
	}
	if home == "" {
		return "", errors.New("resolving home directory: empty home")
	}
	return filepath.Join(home, ".config", "tws", "template-registry"), nil
}

func RepoTemplateRegistryRoot(repoRoot string) (string, error) {
	if repoRoot == "" {
		return "", errors.New("repository template registry requires a repository")
	}
	abs, err := filepath.Abs(repoRoot)
	if err != nil {
		return "", fmt.Errorf("resolving repository root: %w", err)
	}
	return filepath.Join(abs, ".tws", ".template-registry"), nil
}

func templateRegistryRoot(repoRoot, scope string) (string, error) {
	switch scope {
	case TemplateScopeGlobal:
		return GlobalTemplateRegistryRoot()
	case TemplateScopeRepo:
		return RepoTemplateRegistryRoot(repoRoot)
	default:
		return "", fmt.Errorf("unknown template registry scope %q", scope)
	}
}

func ensureTemplateRegistryOriginID(root string) (string, error) {
	identityDir := filepath.Join(root, templateRegistryIdentityDir)
	info, err := os.Lstat(identityDir)
	if errors.Is(err, fs.ErrNotExist) {
		if err := os.Mkdir(identityDir, 0o700); err != nil && !errors.Is(err, fs.ErrExist) {
			return "", fmt.Errorf("creating template registry identity directory: %w", err)
		}
		info, err = os.Lstat(identityDir)
	}
	if err != nil {
		return "", fmt.Errorf("reading template registry identity directory: %w", err)
	}
	if info.Mode()&os.ModeSymlink != 0 || !info.IsDir() {
		return "", fmt.Errorf("template registry identity directory %s is not a regular directory", identityDir)
	}
	identityPath := filepath.Join(identityDir, workspaceMarkerIDFile)
	if identityInfo, identityErr := os.Lstat(identityPath); identityErr == nil {
		if identityInfo.Mode()&os.ModeSymlink != 0 || !identityInfo.Mode().IsRegular() {
			return "", fmt.Errorf("template registry identity %s is not a regular file", identityPath)
		}
	} else if !errors.Is(identityErr, fs.ErrNotExist) {
		return "", fmt.Errorf("reading template registry identity %s: %w", identityPath, identityErr)
	}
	id, err := EnsureWorkspaceMarkerID(identityDir)
	if err != nil {
		return "", fmt.Errorf("ensuring template registry identity: %w", err)
	}
	return id, nil
}

func readTemplateRegistryOriginID(root string) (string, error) {
	identityDir := filepath.Join(root, templateRegistryIdentityDir)
	info, err := os.Lstat(identityDir)
	if err != nil {
		return "", fmt.Errorf("reading template registry identity directory: %w", err)
	}
	if info.Mode()&os.ModeSymlink != 0 || !info.IsDir() {
		return "", fmt.Errorf("template registry identity directory %s is not a regular directory", identityDir)
	}
	identityPath := filepath.Join(identityDir, workspaceMarkerIDFile)
	identityInfo, err := os.Lstat(identityPath)
	if err != nil {
		return "", fmt.Errorf("reading template registry identity %s: %w", identityPath, err)
	}
	if identityInfo.Mode()&os.ModeSymlink != 0 || !identityInfo.Mode().IsRegular() {
		return "", fmt.Errorf("template registry identity %s is not a regular file", identityPath)
	}
	id, err := ReadWorkspaceMarkerID(identityDir)
	if err != nil {
		return "", fmt.Errorf("reading template registry identity: %w", err)
	}
	if id == "" {
		return "", fmt.Errorf("template registry identity %s is missing", identityPath)
	}
	return id, nil
}

func ResolveTemplateReference(repoRoot, value string) (ResolvedTemplate, error) {
	ref, err := ParseTemplateReference(value)
	if err != nil {
		return ResolvedTemplate{}, err
	}
	scopes := []string{ref.Scope}
	if ref.Scope == "" {
		scopes = []string{TemplateScopeRepo, TemplateScopeGlobal}
	}
	for _, scope := range scopes {
		root, rootErr := templateRegistryRoot(repoRoot, scope)
		if rootErr != nil {
			if ref.Scope != "" {
				return ResolvedTemplate{}, rootErr
			}
			continue
		}
		path := filepath.Join(root, ref.Name)
		info, statErr := os.Lstat(path)
		if errors.Is(statErr, fs.ErrNotExist) {
			continue
		}
		if statErr != nil {
			return ResolvedTemplate{}, fmt.Errorf("reading %s template %q: %w", scope, ref.Name, statErr)
		}
		if info.Mode()&os.ModeSymlink != 0 || !info.IsDir() {
			return ResolvedTemplate{}, fmt.Errorf("%s template %q is not a regular directory", scope, ref.Name)
		}
		originID, err := readTemplateRegistryOriginID(root)
		if err != nil {
			return ResolvedTemplate{}, fmt.Errorf("reading %s template %q origin: %w", scope, ref.Name, err)
		}
		return ResolvedTemplate{
			Reference: TemplateReference{Scope: scope, Name: ref.Name},
			Path:      path,
			OriginID:  originID,
		}, nil
	}
	if ref.Scope != "" {
		return ResolvedTemplate{}, fmt.Errorf("%s template %q not found", ref.Scope, ref.Name)
	}
	return ResolvedTemplate{}, fmt.Errorf("template %q not found in the repository or global registry", ref.Name)
}

func ResolvePersistedTemplateReference(repoRoot string, ref TemplateReference) (ResolvedTemplate, error) {
	if ref.Scope != TemplateScopeRepo && ref.Scope != TemplateScopeGlobal {
		return ResolvedTemplate{}, fmt.Errorf("saved template %q has invalid scope %q", ref.Name, ref.Scope)
	}
	return ResolveTemplateReference(repoRoot, ref.Scope+":"+ref.Name)
}

func AddNamedTemplate(repoRoot, scope, name, source string) (retErr error) {
	if err := ValidateTemplateName(name); err != nil {
		return err
	}
	pkg, err := LoadTemplatePackage(source)
	if err != nil {
		return err
	}
	root, err := templateRegistryRoot(repoRoot, scope)
	if err != nil {
		return err
	}
	if err := ensureRegistryRoot(root, templateRegistryAnchor(repoRoot, scope)); err != nil {
		return err
	}
	initialIdentity, err := managedDirectoryIdentity(root)
	if err != nil {
		return err
	}
	if _, err := ensureTemplateRegistryOriginID(root); err != nil {
		return err
	}
	lock, err := acquireTemplateRegistryLock(root)
	if err != nil {
		return err
	}
	defer func() { retErr = errors.Join(retErr, lock.Release()) }()
	if lock.identity != initialIdentity {
		return fmt.Errorf("template registry root identity changed before lock acquisition: %s", root)
	}
	if templateRegistryAfterLockHook != nil {
		if err := templateRegistryAfterLockHook(root); err != nil {
			return err
		}
	}
	if err := lock.verifyPath(); err != nil {
		return err
	}
	if filepath.Clean(lock.root.Name()) != filepath.Clean(root) {
		return fmt.Errorf("template registry root identity changed at %s", root)
	}

	entries, err := listRegistryScopeRoot(lock.root, root, scope)
	if err != nil {
		return err
	}
	for _, entry := range entries {
		if strings.EqualFold(entry.Name, name) {
			return fmt.Errorf("%s template %q conflicts with existing entry %q", scope, name, entry.Name)
		}
	}

	target := filepath.Join(root, name)
	if _, err := lock.root.Lstat(name); !errors.Is(err, fs.ErrNotExist) {
		if err == nil {
			return fmt.Errorf("%s template %q already exists", scope, name)
		}
		return fmt.Errorf("checking template destination %s: %w", target, err)
	}

	stage, err := createTemplateRegistryStage(lock.root, name)
	if err != nil {
		return fmt.Errorf("creating registry staging directory: %w", err)
	}
	defer func() {
		if cleanupErr := lock.root.RemoveAll(stage); cleanupErr != nil && !errors.Is(cleanupErr, fs.ErrNotExist) {
			retErr = errors.Join(retErr, fmt.Errorf("cleaning registry staging directory %s: %w", filepath.Join(root, stage), cleanupErr))
		}
	}()
	stageRoot, err := lock.root.OpenRoot(stage)
	if err != nil {
		return err
	}
	if err := copyTemplatePackageRoot(pkg, stageRoot); err != nil {
		_ = stageRoot.Close()
		return err
	}
	if err := stageRoot.Close(); err != nil {
		return err
	}
	if err := lock.verifyPath(); err != nil {
		return err
	}
	if filepath.Clean(lock.root.Name()) != filepath.Clean(root) {
		return fmt.Errorf("template registry root identity changed at %s", root)
	}
	if err := managedRenameNoReplace(lock.root, stage, name); err != nil {
		return fmt.Errorf("publishing %s template %q: %w", scope, name, err)
	}
	return nil
}

func RemoveNamedTemplate(repoRoot, scope, name string) (retErr error) {
	if err := ValidateTemplateName(name); err != nil {
		return err
	}
	root, err := templateRegistryRoot(repoRoot, scope)
	if err != nil {
		return err
	}
	if err := ensureRegistryRoot(root, templateRegistryAnchor(repoRoot, scope)); err != nil {
		return err
	}
	initialIdentity, err := managedDirectoryIdentity(root)
	if err != nil {
		return err
	}
	lock, err := acquireTemplateRegistryLock(root)
	if err != nil {
		return err
	}
	defer func() { retErr = errors.Join(retErr, lock.Release()) }()
	if lock.identity != initialIdentity {
		return fmt.Errorf("template registry root identity changed before lock acquisition: %s", root)
	}
	if templateRegistryAfterLockHook != nil {
		if err := templateRegistryAfterLockHook(root); err != nil {
			return err
		}
	}
	if err := lock.verifyPath(); err != nil {
		return err
	}

	path := filepath.Join(root, name)
	info, err := lock.root.Lstat(name)
	if errors.Is(err, fs.ErrNotExist) {
		return fmt.Errorf("%s template %q not found", scope, name)
	}
	if err != nil {
		return fmt.Errorf("reading %s template %q: %w", scope, name, err)
	}
	if info.Mode()&os.ModeSymlink != 0 || !info.IsDir() {
		return fmt.Errorf("%s template %q is not a regular directory", scope, name)
	}
	expected, err := managedIdentityFromInfo(info)
	if err != nil {
		return err
	}
	quarantine, err := createTemplateRegistryQuarantineName(lock.root, name)
	if err != nil {
		return err
	}
	if err := lock.verifyPath(); err != nil {
		return err
	}
	if err := managedRenameNoReplace(lock.root, name, quarantine); err != nil {
		return fmt.Errorf("preserving %s template %q before removal: %w", scope, name, err)
	}
	captured, err := lock.root.Lstat(quarantine)
	if err != nil {
		return fmt.Errorf("inspecting preserved template %s: %w", filepath.Join(root, quarantine), err)
	}
	capturedIdentity, err := managedIdentityFromInfo(captured)
	if err != nil {
		return err
	}
	if capturedIdentity != expected || !captured.IsDir() {
		restoreErr := managedRenameNoReplace(lock.root, quarantine, name)
		if restoreErr != nil {
			return fmt.Errorf("template changed during removal; preserved paths: %s and %s: %w",
				path, filepath.Join(root, quarantine), restoreErr)
		}
		return fmt.Errorf("template changed during removal and was restored at %s", path)
	}
	if err := lock.root.RemoveAll(quarantine); err != nil {
		return fmt.Errorf("removing %s template %q: %w", scope, name, err)
	}
	return nil
}

func ListNamedTemplates(repoRoot string) ([]NamedTemplateEntry, error) {
	var entries []NamedTemplateEntry
	if repoRoot != "" {
		root, err := RepoTemplateRegistryRoot(repoRoot)
		if err != nil {
			return nil, err
		}
		repoEntries, err := listRegistryScope(root, TemplateScopeRepo)
		if err != nil {
			return nil, err
		}
		entries = append(entries, repoEntries...)
	}
	globalRoot, err := GlobalTemplateRegistryRoot()
	if err != nil {
		return nil, err
	}
	globalEntries, err := listRegistryScope(globalRoot, TemplateScopeGlobal)
	if err != nil {
		return nil, err
	}
	entries = append(entries, globalEntries...)

	repoNames := make(map[string]bool)
	for _, entry := range entries {
		if entry.Scope == TemplateScopeRepo {
			repoNames[strings.ToLower(entry.Name)] = true
		}
	}
	for i := range entries {
		entries[i].Effective = entries[i].Scope == TemplateScopeRepo ||
			!repoNames[strings.ToLower(entries[i].Name)]
	}
	sort.Slice(entries, func(i, j int) bool {
		if entries[i].Name != entries[j].Name {
			return entries[i].Name < entries[j].Name
		}
		return entries[i].Scope == TemplateScopeRepo
	})
	return entries, nil
}

func ShowNamedTemplate(repoRoot, value string) (ResolvedTemplate, TemplatePackage, error) {
	resolved, err := ResolveTemplateReference(repoRoot, value)
	if err != nil {
		return ResolvedTemplate{}, TemplatePackage{}, err
	}
	pkg, err := LoadTemplatePackage(resolved.Path)
	if err != nil {
		return ResolvedTemplate{}, TemplatePackage{}, err
	}
	return resolved, pkg, nil
}

func listRegistryScope(root, scope string) ([]NamedTemplateEntry, error) {
	info, err := os.Lstat(root)
	if errors.Is(err, fs.ErrNotExist) {
		return nil, nil
	}
	if err != nil {
		return nil, fmt.Errorf("reading %s template registry: %w", scope, err)
	}
	if info.Mode()&os.ModeSymlink != 0 || !info.IsDir() {
		return nil, fmt.Errorf("%s template registry %s is not a regular directory", scope, root)
	}
	rootHandle, err := os.OpenRoot(root)
	if err != nil {
		return nil, fmt.Errorf("opening %s template registry: %w", scope, err)
	}
	defer rootHandle.Close() //nolint:errcheck
	return listRegistryScopeRoot(rootHandle, root, scope)
}

func listRegistryScopeRoot(rootHandle *os.Root, rootPath, scope string) ([]NamedTemplateEntry, error) {
	dirEntries, err := fs.ReadDir(rootHandle.FS(), ".")
	if err != nil {
		return nil, fmt.Errorf("reading %s template registry: %w", scope, err)
	}
	var entries []NamedTemplateEntry
	seen := make(map[string]string)
	for _, entry := range dirEntries {
		if strings.HasPrefix(entry.Name(), ".") {
			continue
		}
		if err := ValidateTemplateName(entry.Name()); err != nil {
			return nil, fmt.Errorf("invalid %s template registry entry %q: %w", scope, entry.Name(), err)
		}
		folded := strings.ToLower(entry.Name())
		if prior := seen[folded]; prior != "" {
			return nil, fmt.Errorf("%s template registry contains aliasing entries %q and %q", scope, prior, entry.Name())
		}
		seen[folded] = entry.Name()
		info, err := entry.Info()
		if err != nil {
			return nil, err
		}
		if info.Mode()&os.ModeSymlink != 0 || !info.IsDir() {
			return nil, fmt.Errorf("%s template registry entry %q is not a regular directory", scope, entry.Name())
		}
		path := filepath.Join(rootPath, entry.Name())
		child, err := rootHandle.OpenRoot(entry.Name())
		if err != nil {
			return nil, fmt.Errorf("opening %s template %q: %w", scope, entry.Name(), err)
		}
		identity, identityErr := managedRootIdentity(child)
		if identityErr != nil {
			_ = child.Close()
			return nil, identityErr
		}
		_, loadErr := loadTemplatePackageRoot(child, path, identity)
		closeErr := child.Close()
		if loadErr != nil {
			return nil, fmt.Errorf("invalid %s template %q: %w", scope, entry.Name(), loadErr)
		}
		if closeErr != nil {
			return nil, closeErr
		}
		entries = append(entries, NamedTemplateEntry{Name: entry.Name(), Scope: scope, Path: path})
	}
	sort.Slice(entries, func(i, j int) bool { return entries[i].Name < entries[j].Name })
	return entries, nil
}

func LoadTemplatePackage(root string) (TemplatePackage, error) {
	abs, err := filepath.Abs(root)
	if err != nil {
		return TemplatePackage{}, fmt.Errorf("resolving template package %s: %w", root, err)
	}
	info, err := os.Lstat(abs)
	if err != nil {
		return TemplatePackage{}, fmt.Errorf("reading template package %s: %w", abs, err)
	}
	if info.Mode()&os.ModeSymlink != 0 || !info.IsDir() {
		return TemplatePackage{}, fmt.Errorf("template package %s must be a regular directory", abs)
	}

	rootHandle, err := os.OpenRoot(abs)
	if err != nil {
		return TemplatePackage{}, fmt.Errorf("opening template package %s: %w", abs, err)
	}
	defer rootHandle.Close() //nolint:errcheck
	identity, err := managedRootIdentity(rootHandle)
	if err != nil {
		return TemplatePackage{}, fmt.Errorf("reading template package identity %s: %w", abs, err)
	}
	if templatePackageAfterOpenHook != nil {
		if err := templatePackageAfterOpenHook(abs); err != nil {
			return TemplatePackage{}, err
		}
	}
	return loadTemplatePackageRoot(rootHandle, abs, identity)
}

func loadTemplatePackageRoot(rootHandle *os.Root, displayPath string, identity managedObjectIdentity) (TemplatePackage, error) {
	pkg := TemplatePackage{Root: displayPath, rootIdentity: identity}
	seen := make(map[string]string)
	err := fs.WalkDir(rootHandle.FS(), ".", func(path string, entry fs.DirEntry, walkErr error) error {
		if walkErr != nil {
			return walkErr
		}
		if path == "." {
			return nil
		}
		rel := filepath.ToSlash(path)
		info, err := entry.Info()
		if err != nil {
			return err
		}
		if info.Mode()&os.ModeSymlink != 0 {
			return fmt.Errorf("template package contains symbolic link %s", rel)
		}
		if !info.IsDir() && !info.Mode().IsRegular() {
			return fmt.Errorf("template package contains special file %s", rel)
		}
		folded := strings.ToLower(rel)
		if prior := seen[folded]; prior != "" {
			return fmt.Errorf("template package paths %q and %q alias under case-insensitive filesystems", prior, rel)
		}
		seen[folded] = rel

		top := strings.SplitN(rel, "/", 2)[0]
		switch top {
		case "feature", "inject":
		case "README.md", "template.yaml":
			if strings.Contains(rel, "/") {
				return fmt.Errorf("unsupported template package entry %s", rel)
			}
		default:
			return fmt.Errorf("unsupported template package entry %s", rel)
		}
		if info.IsDir() {
			if top == "README.md" || top == "template.yaml" {
				return fmt.Errorf("template metadata %s must be a regular file", rel)
			}
			return nil
		}
		switch top {
		case "feature", "inject":
			parts := strings.SplitN(rel, "/", 2)
			if len(parts) != 2 || parts[1] == "" {
				return fmt.Errorf("template payload root %s must be a regular directory", rel)
			}
			if err := validateTemplateAssetPath(parts[1]); err != nil {
				return fmt.Errorf("invalid template asset %s: %w", rel, err)
			}
			data, err := rootHandle.ReadFile(path)
			if err != nil {
				return err
			}
			file := TemplatePackageFile{Path: parts[1], Data: data, Mode: info.Mode().Perm()}
			if top == "feature" {
				pkg.Feature = append(pkg.Feature, file)
			} else {
				pkg.Inject = append(pkg.Inject, file)
			}
		case "README.md", "template.yaml":
			data, err := rootHandle.ReadFile(path)
			if err != nil {
				return err
			}
			pkg.Metadata = append(pkg.Metadata, TemplatePackageFile{
				Path: rel, Data: data, Mode: info.Mode().Perm(),
			})
			if top == "template.yaml" {
				manifest, err := parseTemplateManifest(data)
				if err != nil {
					return fmt.Errorf("parsing template manifest: %w", err)
				}
				pkg.Manifest = manifest
			}
		}
		return nil
	})
	if err != nil {
		return TemplatePackage{}, fmt.Errorf("validating template package %s: %w", displayPath, err)
	}
	sort.Slice(pkg.Feature, func(i, j int) bool { return pkg.Feature[i].Path < pkg.Feature[j].Path })
	sort.Slice(pkg.Inject, func(i, j int) bool { return pkg.Inject[i].Path < pkg.Inject[j].Path })
	sort.Slice(pkg.Metadata, func(i, j int) bool { return pkg.Metadata[i].Path < pkg.Metadata[j].Path })
	return pkg, nil
}

func parseTemplateManifest(data []byte) (TemplateManifest, error) {
	decoder := yaml.NewDecoder(bytes.NewReader(data))
	decoder.KnownFields(true)
	var manifest TemplateManifest
	if err := decoder.Decode(&manifest); err != nil {
		return TemplateManifest{}, err
	}
	var extra any
	if err := decoder.Decode(&extra); !errors.Is(err, io.EOF) {
		if err == nil {
			return TemplateManifest{}, errors.New("manifest contains multiple YAML documents")
		}
		return TemplateManifest{}, err
	}
	if manifest.Version != templateManifestVersion {
		return TemplateManifest{}, fmt.Errorf("unsupported template manifest version %d", manifest.Version)
	}
	for role := range manifest.Guidance {
		if role != string(ManagedTemplateRoleWorktree) && role != string(ManagedTemplateRoleOrchestrator) {
			return TemplateManifest{}, fmt.Errorf("unknown guidance role %q", role)
		}
	}
	seenSkills := make(map[string]bool)
	for i, skill := range manifest.Skills {
		if err := validateSkillName(skill.Name); err != nil {
			return TemplateManifest{}, fmt.Errorf("skill %d: %w", i+1, err)
		}
		if seenSkills[skill.Name] {
			return TemplateManifest{}, fmt.Errorf("duplicate skill reference %q", skill.Name)
		}
		seenSkills[skill.Name] = true
		if len(skill.Roles) == 0 {
			return TemplateManifest{}, fmt.Errorf("skill %q must declare at least one role", skill.Name)
		}
		if err := validateManifestValues("role", skill.Name, skill.Roles,
			string(ManagedTemplateRoleWorktree), string(ManagedTemplateRoleOrchestrator)); err != nil {
			return TemplateManifest{}, err
		}
		if err := validateManifestValues("agent", skill.Name, skill.Agents, "claude", "copilot"); err != nil {
			return TemplateManifest{}, err
		}
	}
	return manifest, nil
}

func validateManifestValues(kind, skill string, values []string, allowed ...string) error {
	seen := make(map[string]bool)
	valid := make(map[string]bool, len(allowed))
	for _, value := range allowed {
		valid[value] = true
	}
	for _, value := range values {
		if !valid[value] {
			return fmt.Errorf("skill %q has unknown %s %q", skill, kind, value)
		}
		if seen[value] {
			return fmt.Errorf("skill %q repeats %s %q", skill, kind, value)
		}
		seen[value] = true
	}
	return nil
}

func validateSkillName(name string) error {
	if name == "" {
		return errors.New("skill name cannot be empty")
	}
	for _, r := range name {
		if unicode.IsControl(r) || r == '/' || r == '\\' || r == ':' || unicode.IsSpace(r) {
			return fmt.Errorf("skill name %q contains an unsafe character", name)
		}
	}
	if name == "." || name == ".." || strings.HasPrefix(name, ".") {
		return fmt.Errorf("skill name %q is hidden or reserved", name)
	}
	return nil
}

func validateTemplateAssetPath(path string) error {
	if path == "" || filepath.IsAbs(path) || strings.Contains(path, "\\") {
		return fmt.Errorf("asset path %q is not a safe relative slash path", path)
	}
	clean := filepath.ToSlash(filepath.Clean(filepath.FromSlash(path)))
	if clean != path || clean == "." || clean == ".." || strings.HasPrefix(clean, "../") {
		return fmt.Errorf("asset path %q is not normalized", path)
	}
	parts := strings.Split(path, "/")
	for i, part := range parts {
		if part == "" || part == "." || part == ".." {
			return fmt.Errorf("asset path %q contains an unsafe component", path)
		}
		for _, r := range part {
			if unicode.IsControl(r) {
				return fmt.Errorf("asset path %q contains a control character", path)
			}
		}
		if strings.EqualFold(part, "SKILL.md") {
			return fmt.Errorf("asset path %q contains a skill implementation; use manifest skill references instead", path)
		}
		if strings.EqualFold(part, "skills") && i > 0 {
			parent := strings.ToLower(parts[i-1])
			if parent == ".claude" || parent == ".github" || parent == ".copilot" {
				return fmt.Errorf("asset path %q contains an agent skill store; use manifest skill references instead", path)
			}
		}
	}
	return nil
}

func copyTemplatePackageRoot(pkg TemplatePackage, destination *os.Root) error {
	for _, dir := range []string{"feature", "inject"} {
		if err := destination.MkdirAll(dir, 0o755); err != nil {
			return err
		}
	}
	for _, group := range []struct {
		prefix string
		files  []TemplatePackageFile
	}{
		{prefix: "feature", files: pkg.Feature},
		{prefix: "inject", files: pkg.Inject},
	} {
		for _, file := range group.files {
			path := filepath.Join(group.prefix, filepath.FromSlash(file.Path))
			if err := destination.MkdirAll(filepath.Dir(path), 0o755); err != nil {
				return err
			}
			if err := writeTemplatePackageRootFile(destination, path, file.Data, file.Mode.Perm()); err != nil {
				return err
			}
		}
	}
	for _, file := range pkg.Metadata {
		if err := writeTemplatePackageRootFile(destination, file.Path, file.Data, file.Mode.Perm()); err != nil {
			return err
		}
	}
	return nil
}

func writeTemplatePackageRootFile(root *os.Root, path string, data []byte, mode fs.FileMode) error {
	file, err := root.OpenFile(path, os.O_WRONLY|os.O_CREATE|os.O_EXCL, mode.Perm())
	if err != nil {
		return err
	}
	if _, err := file.Write(data); err != nil {
		_ = file.Close()
		return err
	}
	if err := file.Sync(); err != nil {
		_ = file.Close()
		return err
	}
	if err := file.Chmod(mode.Perm()); err != nil {
		_ = file.Close()
		return err
	}
	return file.Close()
}

func createTemplateRegistryStage(root *os.Root, name string) (string, error) {
	for attempt := 0; attempt < 32; attempt++ {
		random := make([]byte, 8)
		if _, err := io.ReadFull(rand.Reader, random); err != nil {
			return "", err
		}
		stage := "." + name + "-stage-" + fmt.Sprintf("%x", random)
		if err := root.Mkdir(stage, 0o700); err == nil {
			return stage, nil
		} else if !errors.Is(err, fs.ErrExist) {
			return "", err
		}
	}
	return "", errors.New("could not allocate template registry staging directory")
}

func createTemplateRegistryQuarantineName(root *os.Root, name string) (string, error) {
	for attempt := 0; attempt < 32; attempt++ {
		random := make([]byte, 8)
		if _, err := io.ReadFull(rand.Reader, random); err != nil {
			return "", err
		}
		candidate := ".removed-" + name + "-" + fmt.Sprintf("%x", random)
		if _, err := root.Lstat(candidate); errors.Is(err, fs.ErrNotExist) {
			return candidate, nil
		} else if err != nil {
			return "", err
		}
	}
	return "", errors.New("could not allocate template registry recovery name")
}

func templateRegistryAnchor(repoRoot, scope string) string {
	if scope == TemplateScopeRepo {
		return repoRoot
	}
	home, _ := os.UserHomeDir()
	return home
}

func ensureRegistryRoot(root, anchor string) error {
	if anchor == "" {
		return fmt.Errorf("template registry %s has no trusted anchor", root)
	}
	if err := ensureNoSymlinkParents(anchor, root); err != nil {
		return err
	}
	if err := os.MkdirAll(root, 0o755); err != nil {
		return fmt.Errorf("creating template registry %s: %w", root, err)
	}
	info, err := os.Lstat(root)
	if err != nil {
		return err
	}
	if info.Mode()&os.ModeSymlink != 0 || !info.IsDir() {
		return fmt.Errorf("template registry %s is not a regular directory", root)
	}
	return nil
}

func ensureNoSymlinkParents(anchor, target string) error {
	anchor, err := filepath.Abs(anchor)
	if err != nil {
		return err
	}
	target, err = filepath.Abs(target)
	if err != nil {
		return err
	}
	rel, err := filepath.Rel(anchor, target)
	if err != nil || rel == ".." || strings.HasPrefix(rel, ".."+string(filepath.Separator)) {
		return fmt.Errorf("path %s escapes %s", target, anchor)
	}
	anchorInfo, err := os.Lstat(anchor)
	if err != nil {
		return err
	}
	if anchorInfo.Mode()&os.ModeSymlink != 0 || !anchorInfo.IsDir() {
		return fmt.Errorf("trusted template registry anchor %s is not a regular directory", anchor)
	}
	current := anchor
	for _, part := range strings.Split(rel, string(filepath.Separator)) {
		if part == "" || part == "." {
			continue
		}
		current = filepath.Join(current, part)
		info, err := os.Lstat(current)
		if errors.Is(err, fs.ErrNotExist) {
			continue
		}
		if err != nil {
			return err
		}
		if info.Mode()&os.ModeSymlink != 0 {
			return fmt.Errorf("path %s contains symbolic link component %s", target, current)
		}
	}
	return nil
}

type templateRegistryLock struct {
	root     *os.Root
	file     *os.File
	identity managedObjectIdentity
	path     string
}

func acquireTemplateRegistryLock(rootPath string) (*templateRegistryLock, error) {
	root, err := os.OpenRoot(rootPath)
	if err != nil {
		return nil, fmt.Errorf("opening template registry root: %w", err)
	}
	identity, err := managedRootIdentity(root)
	if err != nil {
		_ = root.Close()
		return nil, err
	}
	file, err := root.OpenFile(".registry.lock", os.O_CREATE|os.O_RDWR, 0o600)
	if err != nil {
		_ = root.Close()
		return nil, fmt.Errorf("opening template registry lock: %w", err)
	}
	if err := flockTryExclusive(file); err != nil {
		_ = file.Close()
		_ = root.Close()
		return nil, fmt.Errorf("template registry is locked by another writer: %w", err)
	}
	if err := managedVerifyPathIdentity(rootPath, identity); err != nil {
		releaseErr := errors.Join(flockUnlock(file), file.Close(), root.Close())
		return nil, errors.Join(err, releaseErr)
	}
	return &templateRegistryLock{
		root: root, file: file, identity: identity, path: rootPath,
	}, nil
}

func (lock *templateRegistryLock) verifyPath() error {
	if lock == nil {
		return errors.New("template registry lock is nil")
	}
	return managedVerifyPathIdentity(lock.path, lock.identity)
}

func (lock *templateRegistryLock) Release() error {
	if lock == nil {
		return nil
	}
	return errors.Join(flockUnlock(lock.file), lock.file.Close(), lock.root.Close())
}

